                <button
                  type="button"
                  class="flow-link"
                  disabled={state.busy[item.id]}
                  onClick$={() => draft(item.id)}
                >
                  {state.busy[item.id] ? "Drafting…" : "Draft it for me"}
                </button>
                <button
                  type="button"
                  class="btn-paper flow-mini"
                  disabled={state.busy[item.id] || !(state.drafts[item.id] ?? "").trim()}
                  onClick$={() => file(item.id)}
                >
                  File it
                </button>
              </div>
              {state.notices[item.id] && (
                <p class="flow-card__notice" role="status">
                  {state.notices[item.id]}
                </p>
              )}
            </div>
          )}

          {(item.byline && item.kind !== "persona-note") || item.url ? (
            <footer class="flow-card__foot">
              {item.byline && item.kind !== "persona-note" && <span>{item.byline}</span>}
              {item.url && item.kind !== "work" && (
                <a
                  href={item.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  class="flow-link"
                  onClick$={() => flowController()?.engage(item.id)}
                >
                  Open
                </a>
              )}
            </footer>
          ) : null}
        </article>
      );
    };

    const room = state.placed.filter((p) => p.side === "room");
    const archive = state.placed.filter((p) => p.side === "archive");
    const waiting = state.held > 0 && state.enabled && state.mode !== "flow";

    return (
      <div
        ref={root}
        class="flow-surface"
        data-mode={state.mode}
        aria-label="Margin notes and connections"
      >
        <svg
          class="flow-overlay"
          width={state.width}
          height={state.height}
          aria-hidden="true"
        >
          {state.marks.map((m, i) => (
            <rect
              key={`m${i}`}
              class="flow-overlay__mark"
              x={m.x - 1}
              y={m.y + m.h - 3}
              width={m.w + 2}
              height={3}
              style={{ fill: m.color }}
            />
          ))}
          {state.brackets.map((b, i) => (
            <path key={`b${i}`} class="flow-overlay__bracket" d={b.d} style={{ stroke: b.color }} />
          ))}
          {state.lines.map((l, i) => (
            <path
              key={`l${i}`}
              class={["flow-overlay__line", { "is-dashed": l.dashed }]}
              d={l.d}
              style={{ stroke: l.color }}
            />
          ))}
        </svg>

        {state.archive && (
          <div class="flow-column flow-column--archive" style={{ width: `${ARCHIVE_WIDTH}px` }}>
            {archive.map(card)}
          </div>
        )}

        {state.room === "rail" ? (
          <div class="flow-column flow-column--room" style={{ width: `${ROOM_WIDTH}px` }}>
            {room.map(card)}
            {waiting && (
              <button
                type="button"
                class="flow-waiting"
                style={{
                  top: `${Math.max(0, ...room.map((p) => p.top + 140))}px`,
                }}
                onClick$={() => {
                  state.expanded = !state.expanded;
                  window.dispatchEvent(new CustomEvent("twyne:content"));
                }}
              >
                {state.expanded ? "Fewer" : `${state.held} more in the margin`}
              </button>
            )}
          </div>
        ) : (
          room.length > 0 && (
            <div class="flow-dock" role="complementary" aria-label="From the margin">
              {card({ ...room[0], top: 0 })}
              {room.length + state.held > 1 && (
                <p class="flow-dock__more">
                  {room.length + state.held - 1} more when there's room
                </p>
              )}
            </div>
          )
        )}
      </div>
    );
  },
);

