/* The House — a publishing house's front office, c. 1950: a letterhead,
   a filing cabinet, a typed sheet in the platen, a register in the back.
   Every colour is a theme token, so the dark and cool presets carry it. */

.house {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-serif);
}
.house__inner {
  max-width: 76rem;
  margin: 0 auto;
  padding: 2rem 1.5rem 5rem;
}
@media (max-width: 640px) {
  .house__inner {
    padding: 1.25rem 1rem 4rem;
  }
}

/* ── Letterhead ─────────────────────────────────────────────────── */
.house-letterhead {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 3px double var(--color-ink);
}
.house-letterhead__eyebrow {
  font: 0.62rem/1 var(--font-typewriter);
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-letterhead__name {
  display: block;
  width: 100%;
  margin-top: 0.4rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 clamp(1.8rem, 4vw, 2.75rem) / 1.05 var(--font-display);
  letter-spacing: -0.01em;
}
.house-letterhead__name:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-letterhead__name::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.6;
}
.house-letterhead__motto {
  margin-top: 0.35rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-letterhead__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}
@media (max-width: 640px) {
  .house-letterhead {
    grid-template-columns: 1fr;
  }
  .house-letterhead__actions {
    justify-content: flex-start;
  }
}

/* ── Tabs, as index-card dividers ───────────────────────────────── */
.house-tabs {
  display: flex;
  gap: 0.25rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid var(--color-paper-3);
  overflow-x: auto;
  scrollbar-width: none;
}
.house-tab {
  position: relative;
  flex-shrink: 0;
  padding: 0.55rem 1rem 0.5rem;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 6px 6px 0 0;
  background: none;
  color: var(--color-ink-muted);
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
}
.house-tab:hover {
  color: var(--color-ink);
}
.house-tab[aria-selected="true"] {
  margin-bottom: -1px;
  border-color: var(--color-paper-3);
  background: var(--color-paper);
  color: var(--color-ink);
}
.house-tab__count {
  margin-left: 0.4rem;
  color: var(--color-vermilion);
}

/* ── Cabinet layout: diagram left, sheet right ──────────────────── */
.house-cabinet {
  display: grid;
  grid-template-columns: minmax(18rem, 26rem) 1fr;
  gap: 2rem;
  padding-top: 1.75rem;
}
@media (max-width: 900px) {
  .house-cabinet {
    grid-template-columns: 1fr;
  }
}

/* ── The diagram ────────────────────────────────────────────────── */
.house-diagram {
  position: sticky;
  top: 1.25rem;
  align-self: start;
}
@media (max-width: 900px) {
  .house-diagram {
    position: static;
  }
}
.house-diagram__caption {
  margin: 0 0 0.75rem;
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-tree {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
/* Letterhead node */
.house-node {
  position: relative;
  display: block;
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease;
}
.house-node:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node[aria-current="true"] {
  border-color: var(--color-ink);
  box-shadow:
    inset 0 0 0 1px var(--color-ink),
    0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node__kind {
  display: block;
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-node__name {
  display: block;
  margin-top: 0.15rem;
  font: 700 1rem/1.2 var(--font-display);
}
.house-node__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}
.house-node--house {
  border-top: 4px solid var(--color-vermilion);
  background: linear-gradient(
    var(--color-paper),
    color-mix(in srgb, var(--color-paper) 92%, var(--color-vermilion) 3%)
  );
}
/* A collection is a cabinet drawer: brass label holder, pull. */
.house-drawer {
  position: relative;
  margin-left: 1.1rem;
}
.house-drawer::before {
  content: "";
  position: absolute;
  left: -0.75rem;
  top: -0.6rem;
  bottom: 1.2rem;
  border-left: 1px dashed var(--color-ink-muted);
  opacity: 0.6;
}
.house-node--collection {
  padding-left: 2.6rem;
  background: var(--color-paper-2);
  border-bottom-width: 3px;
}
.house-node--collection::before {
  /* the label holder */
  content: "";
  position: absolute;
  left: 0.75rem;
  top: 50%;
  width: 1.1rem;
  height: 0.7rem;
  transform: translateY(-50%);
  border: 1.5px solid var(--color-mustard);
  border-radius: 1px;
  background: color-mix(in srgb, var(--color-mustard) 12%, transparent);
}
.house-node--loose {
  border-style: dashed;
  background: transparent;
}
.house-node--loose::before {
  border-color: var(--color-ink-muted);
  background: none;
}
/* Folios are manila folders with a tab, standing in the drawer. */
.house-folders {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0.35rem 0 0.2rem 1.2rem;
}
.house-folder {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.6rem 0.4rem;
  margin-top: 0.35rem;
  border: 1px solid color-mix(in srgb, var(--color-mustard) 45%, var(--color-paper-3));
  border-radius: 0 3px 3px 3px;
  background: color-mix(in srgb, var(--color-paper) 82%, var(--color-mustard) 14%);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 140ms ease;
}
.house-folder::before {
  /* the tab */
  content: "";
  position: absolute;
  left: -1px;
  top: -0.4rem;
  width: 2.6rem;
  height: 0.4rem;
  border: inherit;
  border-bottom: 0;
  border-radius: 3px 3px 0 0;
  background: inherit;
}
.house-folder:hover {
  transform: translateX(2px);
}
.house-folder[aria-current="true"] {
  border-color: var(--color-ink);
}
.house-folder__name {
  font: 0.86rem/1.25 var(--font-display);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.house-folder__marks {
  display: flex;
  gap: 0.25rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-folder__empty {
  margin: 0.2rem 0 0;
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Chips: typed tags */
.house-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.05rem 0.4rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-soft);
  font: 0.6rem/1.5 var(--font-typewriter);
  letter-spacing: 0.04em;
  color: var(--color-ink-light);
}
.house-chip--must {
  border-color: color-mix(in srgb, var(--color-vermilion) 50%, transparent);
  color: var(--color-vermilion);
}

/* The legend under the tree: how the stack pours down. */
.house-legend {
  margin-top: 1.25rem;
  padding: 0.85rem 0.9rem;
  border: 1px dashed var(--color-paper-3);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--color-ink-light);
}
.house-legend dt {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink);
}
.house-legend dd {
  margin: 0.1rem 0 0.55rem;
}
.house-legend dd:last-child {
  margin-bottom: 0;
}

/* ── The sheet in the platen ───────────────────────────────────── */
.house-sheet {
  position: relative;
  padding: 2rem 2.25rem 2.25rem;
  background: var(--color-editor-bg);
  border: 1px solid var(--color-paper-3);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 22px 40px -32px rgb(0 0 0 / 0.55);
  animation: house-sheet-in 260ms ease-out;
}
@keyframes house-sheet-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@media (max-width: 640px) {
  .house-sheet {
    padding: 1.25rem 1rem 1.5rem;
  }
}
.house-sheet__kicker {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-sheet__title {
  display: block;
  width: 100%;
  margin: 0.35rem 0 0.25rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 1.6rem/1.15 var(--font-display);
}
.house-sheet__title:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-sheet__lede {
  margin: 0 0 1.5rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-section {
  margin-top: 1.75rem;
}
.house-section:first-of-type {
  margin-top: 0;
}
.house-section__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.35rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-ink);
}
.house-section__title {
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.house-section__note {
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Dossier fields: typed lines on a form. The source layer is stamped. */
.house-fields {
  display: flex;
  flex-direction: column;
}
.house-field {
  display: grid;
  grid-template-columns: 8.5rem 1fr;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
@media (max-width: 640px) {
  .house-field {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }
}
.house-field__label {
  padding-top: 0.3rem;
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-field__value {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 0;
}
.house-input {
  width: 100%;
  padding: 0.25rem 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--color-ink);
  font: 0.95rem/1.5 var(--font-typewriter);
  resize: none;
  field-sizing: content;
  min-height: 1.6rem;
}
.house-input::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.55;
  font-style: italic;
}
.house-input:hover {
  border-bottom-color: var(--color-paper-3);
}
.house-input:focus {
  outline: none;
  border-bottom-color: var(--color-vermilion);
}
.house-input[readonly] {
  cursor: default;
  border-bottom-color: transparent;
}
.house-inherit {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  font: 0.72rem/1.4 var(--font-serif);
  color: var(--color-ink-muted);
}
.house-inherit s {
  opacity: 0.7;
}
/* A layer stamp — the rubber stamp each field carries. */
.house-stamp {
  display: inline-block;
  padding: 0 0.3rem;
  border: 1.25px solid currentColor;
  border-radius: 2px;
  font: 0.54rem/1.5 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-2deg);
  mix-blend-mode: multiply;
}
.house-stamp--house {
  color: var(--color-vermilion);
}
.house-stamp--collection {
  color: var(--color-mustard);
}
.house-stamp--folio {
  color: var(--color-cobalt);
}
.house-stamp--amendment {
  color: var(--color-writer-note);
}
.house-stamp--charter {
  color: var(--color-sage);
}

/* The charter: numbered articles. */
.house-charter {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: article;
}
.house-article {
  counter-increment: article;
  display: grid;
  grid-template-columns: 2.4rem 1fr auto;
  gap: 0.5rem;
  align-items: start;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
.house-article::before {
  content: "Art. " counter(article);
  padding-top: 0.3rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-article__text {
  font: 0.92rem/1.5 var(--font-typewriter);
}
.house-article__controls {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.house-severity {
  padding: 0.05rem 0.4rem;
  border: 1.25px solid var(--color-paper-3);
  border-radius: 2px;
  background: none;
  font: 0.58rem/1.5 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
  cursor: pointer;
}
.house-severity[data-severity="must"] {
  border-color: var(--color-vermilion);
  color: var(--color-vermilion);
}
.house-remove {
  border: 0;
  background: none;
  color: var(--color-ink-muted);
  font-size: 0.75rem;
  cursor: pointer;
  opacity: 0.5;
}
.house-article:hover .house-remove,
.house-remove:focus-visible {
  opacity: 1;
}
.house-remove:hover {
  color: var(--color-vermilion);
}
.house-article--inherited {
  opacity: 0.8;
}
.house-article--inherited .house-article__text {
  color: var(--color-ink-light);
}
.house-new-article {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.5rem;
  margin-top: 0.75rem;
}
@media (max-width: 640px) {
  .house-new-article {
    grid-template-columns: 1fr auto;
  }
  .house-new-article .btn-press {
    grid-column: 1 / -1;
  }
}
.house-new-article input {
  padding: 0.45rem 0.6rem;
  border: 1px dashed var(--color-paper-3);
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font: 0.88rem var(--font-typewriter);
}
.house-new-article input:focus {
  outline: none;
  border-style: solid;
  border-color: var(--color-ink);
}

/* Members of a collection: folders to file in and out. */
.house-members {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  gap: 0.5rem;
}
.house-member {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  font: 0.85rem var(--font-display);
  cursor: pointer;
}
.house-member input {
  accent-color: var(--color-vermilion);
}
.house-member small {
  display: block;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}

/* The model's copy: exactly what is sent. */
.house-carbon {
  margin: 0;
  padding: 1rem 1.1rem;
  border: 1px solid var(--color-paper-3);
  background: repeating-linear-gradient(
    var(--color-paper-soft) 0 1.55rem,
    var(--color-editor-line) 1.55rem calc(1.55rem + 1px)
  );
  color: color-mix(in srgb, var(--color-cobalt) 75%, var(--color-ink));
  font: 0.8rem/1.55rem var(--font-typewriter);
  white-space: pre-wrap;
  word-break: break-word;
}
.house-costs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.house-sheet__foot {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: space-between;
  align-items: center;
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid var(--color-paper-3);
}
.house-saved {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.08em;
  color: var(--color-ink-muted);
}
.house-saved--error {
  color: var(--color-vermilion);
}

/* ── The register (ledger) ─────────────────────────────────────── */
.house-register {
  margin-top: 1.75rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-register__row {
  display: grid;
  grid-template-columns: 7.5rem 9rem 1fr;
  gap: 1rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--color-editor-line);
}
.house-register__row:last-child {
  border-bottom: 0;
}
@media (max-width: 720px) {
  .house-register__row {
    grid-template-columns: 1fr;
    gap: 0.3rem;
  }
}
.house-register__when {
  font: 0.66rem/1.5 var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-register__what {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  font-size: 0.86rem;
}
.house-register__diff {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font: 0.8rem/1.45 var(--font-typewriter);
}
.house-register__from {
  color: var(--color-ink-muted);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--color-vermilion) 60%, transparent);
}
.house-register__why {
  font: italic 0.8rem var(--font-serif);
  color: var(--color-ink-light);
}
/* An amendment is a slip pasted into the register. */
.house-register__row--amendment {
  background: color-mix(in srgb, var(--color-editor-bg) 88%, var(--color-writer-note) 6%);
  box-shadow: inset 3px 0 0 var(--color-writer-note);
}
.house-register__filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 1.5rem;
}
.house-filter {
  padding: 0.2rem 0.6rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 999px;
  background: none;
  color: var(--color-ink-muted);
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.06em;
  cursor: pointer;
}
.house-filter[aria-pressed="true"] {
  border-color: var(--color-ink);
  color: var(--color-ink);
  background: var(--color-paper);
}

.house-empty {
  padding: 2.5rem 1rem;
  text-align: center;
  color: var(--color-ink-muted);
  font-style: italic;
}

/* ── The engine room (diagnostics) ─────────────────────────────── */
.house-engine {
  margin-top: 1.75rem;
  display: grid;
  gap: 1.25rem;
}
.house-gauges {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(10.5rem, 1fr));
  gap: 0.6rem;
}
.house-gauge {
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-gauge__label {
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-gauge__value {
  margin-top: 0.2rem;
  font: 700 1.2rem/1.2 var(--font-display);
  font-variant-numeric: tabular-nums;
}
.house-gauge__hint {
  margin-top: 0.15rem;
  font-size: 0.72rem;
  color: var(--color-ink-muted);
}
.house-weights {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.house-weight {
  display: grid;
  grid-template-columns: 8rem 1fr 3rem;
  gap: 0.6rem;
  align-items: center;
  font: 0.7rem var(--font-typewriter);
}
.house-weight__bar {
  position: relative;
  height: 6px;
  background: var(--color-paper-2);
}
.house-weight__bar span {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--color-cobalt);
}
.house-weight__bar::after {
  /* the neutral line at 1.0 */
  content: "";
  position: absolute;
  left: 55.5%;
  top: -3px;
  bottom: -3px;
  border-left: 1px solid var(--color-ink-muted);
}
.house-log {
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
  max-height: 32rem;
  overflow: auto;
}
.house-log__row {
  display: grid;
  grid-template-columns: 5.5rem 5rem 1fr;
  gap: 0.75rem;
  padding: 0.4rem 0.8rem;
  border-bottom: 1px solid var(--color-editor-line);
  font: 0.7rem/1.5 var(--font-typewriter);
}
.house-log__row summary {
  cursor: pointer;
  list-style: none;
}
.house-log__row summary::-webkit-details-marker {
  display: none;
}
.house-log__kind {
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.house-log__kind--mode {
  color: var(--color-cobalt);
}
.house-log__kind--jev {
  color: var(--color-writer-note);
}
.house-log__kind--surface,
.house-log__kind--item {
  color: var(--color-sage);
}
.house-log__kind--focus {
  color: var(--color-mustard);
}
.house-log__kind--error {
  color: var(--color-vermilion);
}
.house-log pre {
  margin: 0.4rem 0 0.2rem;
  padding: 0.5rem;
  background: var(--color-paper-2);
  font-size: 0.66rem;
  white-space: pre-wrap;
  word-break: break-word;
}

@media (prefers-reduced-motion: reduce) {
  .house-sheet,
  .house-node,
  .house-folder {
    animation: none;
    transition: none;
  }
}

toolu_01WKceop6oSNzhyEdeuqLXmg.content:
/* The House — a publishing house's front office, c. 1950: a letterhead,
   a filing cabinet, a typed sheet in the platen, a register in the back.
   Every colour is a theme token, so the dark and cool presets carry it. */

.house {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-serif);
}
.house__inner {
  max-width: 76rem;
  margin: 0 auto;
  padding: 2rem 1.5rem 5rem;
}
@media (max-width: 640px) {
  .house__inner {
    padding: 1.25rem 1rem 4rem;
  }
}

/* ── Letterhead ─────────────────────────────────────────────────── */
.house-letterhead {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 3px double var(--color-ink);
}
.house-letterhead__eyebrow {
  font: 0.62rem/1 var(--font-typewriter);
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-letterhead__name {
  display: block;
  width: 100%;
  margin-top: 0.4rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 clamp(1.8rem, 4vw, 2.75rem) / 1.05 var(--font-display);
  letter-spacing: -0.01em;
}
.house-letterhead__name:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-letterhead__name::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.6;
}
.house-letterhead__motto {
  margin-top: 0.35rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-letterhead__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}
@media (max-width: 640px) {
  .house-letterhead {
    grid-template-columns: 1fr;
  }
  .house-letterhead__actions {
    justify-content: flex-start;
  }
}

/* ── Tabs, as index-card dividers ───────────────────────────────── */
.house-tabs {
  display: flex;
  gap: 0.25rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid var(--color-paper-3);
  overflow-x: auto;
  scrollbar-width: none;
}
.house-tab {
  position: relative;
  flex-shrink: 0;
  padding: 0.55rem 1rem 0.5rem;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 6px 6px 0 0;
  background: none;
  color: var(--color-ink-muted);
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
}
.house-tab:hover {
  color: var(--color-ink);
}
.house-tab[aria-selected="true"] {
  margin-bottom: -1px;
  border-color: var(--color-paper-3);
  background: var(--color-paper);
  color: var(--color-ink);
}
.house-tab__count {
  margin-left: 0.4rem;
  color: var(--color-vermilion);
}

/* ── Cabinet layout: diagram left, sheet right ──────────────────── */
.house-cabinet {
  display: grid;
  grid-template-columns: minmax(18rem, 26rem) 1fr;
  gap: 2rem;
  padding-top: 1.75rem;
}
@media (max-width: 900px) {
  .house-cabinet {
    grid-template-columns: 1fr;
  }
}

/* ── The diagram ────────────────────────────────────────────────── */
.house-diagram {
  position: sticky;
  top: 1.25rem;
  align-self: start;
}
@media (max-width: 900px) {
  .house-diagram {
    position: static;
  }
}
.house-diagram__caption {
  margin: 0 0 0.75rem;
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-tree {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
/* Letterhead node */
.house-node {
  position: relative;
  display: block;
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease;
}
.house-node:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node[aria-current="true"] {
  border-color: var(--color-ink);
  box-shadow:
    inset 0 0 0 1px var(--color-ink),
    0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node__kind {
  display: block;
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-node__name {
  display: block;
  margin-top: 0.15rem;
  font: 700 1rem/1.2 var(--font-display);
}
.house-node__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}
.house-node--house {
  border-top: 4px solid var(--color-vermilion);
  background: linear-gradient(
    var(--color-paper),
    color-mix(in srgb, var(--color-paper) 92%, var(--color-vermilion) 3%)
  );
}
/* A collection is a cabinet drawer: brass label holder, pull. */
.house-drawer {
  position: relative;
  margin-left: 1.1rem;
}
.house-drawer::before {
  content: "";
  position: absolute;
  left: -0.75rem;
  top: -0.6rem;
  bottom: 1.2rem;
  border-left: 1px dashed var(--color-ink-muted);
  opacity: 0.6;
}
.house-node--collection {
  padding-left: 2.6rem;
  background: var(--color-paper-2);
  border-bottom-width: 3px;
}
.house-node--collection::before {
  /* the label holder */
  content: "";
  position: absolute;
  left: 0.75rem;
  top: 50%;
  width: 1.1rem;
  height: 0.7rem;
  transform: translateY(-50%);
  border: 1.5px solid var(--color-mustard);
  border-radius: 1px;
  background: color-mix(in srgb, var(--color-mustard) 12%, transparent);
}
.house-node--loose {
  border-style: dashed;
  background: transparent;
}
.house-node--loose::before {
  border-color: var(--color-ink-muted);
  background: none;
}
/* Folios are manila folders with a tab, standing in the drawer. */
.house-folders {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0.35rem 0 0.2rem 1.2rem;
}
.house-folder {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.6rem 0.4rem;
  margin-top: 0.35rem;
  border: 1px solid color-mix(in srgb, var(--color-mustard) 45%, var(--color-paper-3));
  border-radius: 0 3px 3px 3px;
  background: color-mix(in srgb, var(--color-paper) 82%, var(--color-mustard) 14%);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 140ms ease;
}
.house-folder::before {
  /* the tab */
  content: "";
  position: absolute;
  left: -1px;
  top: -0.4rem;
  width: 2.6rem;
  height: 0.4rem;
  border: inherit;
  border-bottom: 0;
  border-radius: 3px 3px 0 0;
  background: inherit;
}
.house-folder:hover {
  transform: translateX(2px);
}
.house-folder[aria-current="true"] {
  border-color: var(--color-ink);
}
.house-folder__name {
  font: 0.86rem/1.25 var(--font-display);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.house-folder__marks {
  display: flex;
  gap: 0.25rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-folder__empty {
  margin: 0.2rem 0 0;
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Chips: typed tags */
.house-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.05rem 0.4rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-soft);
  font: 0.6rem/1.5 var(--font-typewriter);
  letter-spacing: 0.04em;
  color: var(--color-ink-light);
}
.house-chip--must {
  border-color: color-mix(in srgb, var(--color-vermilion) 50%, transparent);
  color: var(--color-vermilion);
}

/* The legend under the tree: how the stack pours down. */
.house-legend {
  margin-top: 1.25rem;
  padding: 0.85rem 0.9rem;
  border: 1px dashed var(--color-paper-3);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--color-ink-light);
}
.house-legend dt {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink);
}
.house-legend dd {
  margin: 0.1rem 0 0.55rem;
}
.house-legend dd:last-child {
  margin-bottom: 0;
}

/* ── The sheet in the platen ───────────────────────────────────── */
.house-sheet {
  position: relative;
  padding: 2rem 2.25rem 2.25rem;
  background: var(--color-editor-bg);
  border: 1px solid var(--color-paper-3);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 22px 40px -32px rgb(0 0 0 / 0.55);
  animation: house-sheet-in 260ms ease-out;
}
@keyframes house-sheet-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@media (max-width: 640px) {
  .house-sheet {
    padding: 1.25rem 1rem 1.5rem;
  }
}
.house-sheet__kicker {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-sheet__title {
  display: block;
  width: 100%;
  margin: 0.35rem 0 0.25rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 1.6rem/1.15 var(--font-display);
}
.house-sheet__title:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-sheet__lede {
  margin: 0 0 1.5rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-section {
  margin-top: 1.75rem;
}
.house-section:first-of-type {
  margin-top: 0;
}
.house-section__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.35rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-ink);
}
.house-section__title {
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.house-section__note {
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Dossier fields: typed lines on a form. The source layer is stamped. */
.house-fields {
  display: flex;
  flex-direction: column;
}
.house-field {
  display: grid;
  grid-template-columns: 8.5rem 1fr;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
@media (max-width: 640px) {
  .house-field {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }
}
.house-field__label {
  padding-top: 0.3rem;
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-field__value {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 0;
}
.house-input {
  width: 100%;
  padding: 0.25rem 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--color-ink);
  font: 0.95rem/1.5 var(--font-typewriter);
  resize: none;
  field-sizing: content;
  min-height: 1.6rem;
}
.house-input::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.55;
  font-style: italic;
}
.house-input:hover {
  border-bottom-color: var(--color-paper-3);
}
.house-input:focus {
  outline: none;
  border-bottom-color: var(--color-vermilion);
}
.house-input[readonly] {
  cursor: default;
  border-bottom-color: transparent;
}
.house-inherit {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  font: 0.72rem/1.4 var(--font-serif);
  color: var(--color-ink-muted);
}
.house-inherit s {
  opacity: 0.7;
}
/* A layer stamp — the rubber stamp each field carries. */
.house-stamp {
  display: inline-block;
  padding: 0 0.3rem;
  border: 1.25px solid currentColor;
  border-radius: 2px;
  font: 0.54rem/1.5 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-2deg);
  mix-blend-mode: multiply;
}
.house-stamp--house {
  color: var(--color-vermilion);
}
.house-stamp--collection {
  color: var(--color-mustard);
}
.house-stamp--folio {
  color: var(--color-cobalt);
}
.house-stamp--amendment {
  color: var(--color-writer-note);
}
.house-stamp--charter {
  color: var(--color-sage);
}

/* The charter: numbered articles. */
.house-charter {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: article;
}
.house-article {
  counter-increment: article;
  display: grid;
  grid-template-columns: 2.4rem 1fr auto;
  gap: 0.5rem;
  align-items: start;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
.house-article::before {
  content: "Art. " counter(article);
  padding-top: 0.3rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-article__text {
  font: 0.92rem/1.5 var(--font-typewriter);
}
.house-article__controls {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.house-severity {
  padding: 0.05rem 0.4rem;
  border: 1.25px solid var(--color-paper-3);
  border-radius: 2px;
  background: none;
  font: 0.58rem/1.5 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
  cursor: pointer;
}
.house-severity[data-severity="must"] {
  border-color: var(--color-vermilion);
  color: var(--color-vermilion);
}
.house-remove {
  border: 0;
  background: none;
  color: var(--color-ink-muted);
  font-size: 0.75rem;
  cursor: pointer;
  opacity: 0.5;
}
.house-article:hover .house-remove,
.house-remove:focus-visible {
  opacity: 1;
}
.house-remove:hover {
  color: var(--color-vermilion);
}
.house-article--inherited {
  opacity: 0.8;
}
.house-article--inherited .house-article__text {
  color: var(--color-ink-light);
}
.house-new-article {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.5rem;
  margin-top: 0.75rem;
}
@media (max-width: 640px) {
  .house-new-article {
    grid-template-columns: 1fr auto;
  }
  .house-new-article .btn-press {
    grid-column: 1 / -1;
  }
}
.house-new-article input {
  padding: 0.45rem 0.6rem;
  border: 1px dashed var(--color-paper-3);
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font: 0.88rem var(--font-typewriter);
}
.house-new-article input:focus {
  outline: none;
  border-style: solid;
  border-color: var(--color-ink);
}

/* Members of a collection: folders to file in and out. */
.house-members {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  gap: 0.5rem;
}
.house-member {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  font: 0.85rem var(--font-display);
  cursor: pointer;
}
.house-member input {
  accent-color: var(--color-vermilion);
}
.house-member small {
  display: block;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}

/* The model's copy: exactly what is sent. */
.house-carbon {
  margin: 0;
  padding: 1rem 1.1rem;
  border: 1px solid var(--color-paper-3);
  background: repeating-linear-gradient(
    var(--color-paper-soft) 0 1.55rem,
    var(--color-editor-line) 1.55rem calc(1.55rem + 1px)
  );
  color: color-mix(in srgb, var(--color-cobalt) 75%, var(--color-ink));
  font: 0.8rem/1.55rem var(--font-typewriter);
  white-space: pre-wrap;
  word-break: break-word;
}
.house-costs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.house-sheet__foot {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: space-between;
  align-items: center;
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid var(--color-paper-3);
}
.house-saved {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.08em;
  color: var(--color-ink-muted);
}
.house-saved--error {
  color: var(--color-vermilion);
}

/* ── The register (ledger) ─────────────────────────────────────── */
.house-register {
  margin-top: 1.75rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-register__row {
  display: grid;
  grid-template-columns: 7.5rem 9rem 1fr;
  gap: 1rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--color-editor-line);
}
.house-register__row:last-child {
  border-bottom: 0;
}
@media (max-width: 720px) {
  .house-register__row {
    grid-template-columns: 1fr;
    gap: 0.3rem;
  }
}
.house-register__when {
  font: 0.66rem/1.5 var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-register__what {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  font-size: 0.86rem;
}
.house-register__diff {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font: 0.8rem/1.45 var(--font-typewriter);
}
.house-register__from {
  color: var(--color-ink-muted);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--color-vermilion) 60%, transparent);
}
.house-register__why {
  font: italic 0.8rem var(--font-serif);
  color: var(--color-ink-light);
}
/* An amendment is a slip pasted into the register. */
.house-register__row--amendment {
  background: color-mix(in srgb, var(--color-editor-bg) 88%, var(--color-writer-note) 6%);
  box-shadow: inset 3px 0 0 var(--color-writer-note);
}
.house-register__filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 1.5rem;
}
.house-filter {
  padding: 0.2rem 0.6rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 999px;
  background: none;
  color: var(--color-ink-muted);
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.06em;
  cursor: pointer;
}
.house-filter[aria-pressed="true"] {
  border-color: var(--color-ink);
  color: var(--color-ink);
  background: var(--color-paper);
}

.house-empty {
  padding: 2.5rem 1rem;
  text-align: center;
  color: var(--color-ink-muted);
  font-style: italic;
}

/* ── The engine room (diagnostics) ─────────────────────────────── */
.house-engine {
  margin-top: 1.75rem;
  display: grid;
  gap: 1.25rem;
}
.house-gauges {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(10.5rem, 1fr));
  gap: 0.6rem;
}
.house-gauge {
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-gauge__label {
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-gauge__value {
  margin-top: 0.2rem;
  font: 700 1.2rem/1.2 var(--font-display);
  font-variant-numeric: tabular-nums;
}
.house-gauge__hint {
  margin-top: 0.15rem;
  font-size: 0.72rem;
  color: var(--color-ink-muted);
}
.house-weights {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.house-weight {
  display: grid;
  grid-template-columns: 8rem 1fr 3rem;
  gap: 0.6rem;
  align-items: center;
  font: 0.7rem var(--font-typewriter);
}
.house-weight__bar {
  position: relative;
  height: 6px;
  background: var(--color-paper-2);
}
.house-weight__bar span {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--color-cobalt);
}
.house-weight__bar::after {
  /* the neutral line at 1.0 */
  content: "";
  position: absolute;
  left: 55.5%;
  top: -3px;
  bottom: -3px;
  border-left: 1px solid var(--color-ink-muted);
}
.house-log {
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
  max-height: 32rem;
  overflow: auto;
}
.house-log__row {
  display: grid;
  grid-template-columns: 5.5rem 5rem 1fr;
  gap: 0.75rem;
  padding: 0.4rem 0.8rem;
  border-bottom: 1px solid var(--color-editor-line);
  font: 0.7rem/1.5 var(--font-typewriter);
}
.house-log__row summary {
  cursor: pointer;
  list-style: none;
}
.house-log__row summary::-webkit-details-marker {
  display: none;
}
.house-log__kind {
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.house-log__kind--mode {
  color: var(--color-cobalt);
}
.house-log__kind--jev {
  color: var(--color-writer-note);
}
.house-log__kind--surface,
.house-log__kind--item {
  color: var(--color-sage);
}
.house-log__kind--focus {
  color: var(--color-mustard);
}
.house-log__kind--error {
  color: var(--color-vermilion);
}
.house-log pre {
  margin: 0.4rem 0 0.2rem;
  padding: 0.5rem;
  background: var(--color-paper-2);
  font-size: 0.66rem;
  white-space: pre-wrap;
  word-break: break-word;
}

@media (prefers-reduced-motion: reduce) {
  .house-sheet,
  .house-node,
  .house-folder {
    animation: none;
    transition: none;
  }
}

toolUseResult.content:
/* The House — a publishing house's front office, c. 1950: a letterhead,
   a filing cabinet, a typed sheet in the platen, a register in the back.
   Every colour is a theme token, so the dark and cool presets carry it. */

.house {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-serif);
}
.house__inner {
  max-width: 76rem;
  margin: 0 auto;
  padding: 2rem 1.5rem 5rem;
}
@media (max-width: 640px) {
  .house__inner {
    padding: 1.25rem 1rem 4rem;
  }
}

/* ── Letterhead ─────────────────────────────────────────────────── */
.house-letterhead {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 3px double var(--color-ink);
}
.house-letterhead__eyebrow {
  font: 0.62rem/1 var(--font-typewriter);
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-letterhead__name {
  display: block;
  width: 100%;
  margin-top: 0.4rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 clamp(1.8rem, 4vw, 2.75rem) / 1.05 var(--font-display);
  letter-spacing: -0.01em;
}
.house-letterhead__name:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-letterhead__name::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.6;
}
.house-letterhead__motto {
  margin-top: 0.35rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-letterhead__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}
@media (max-width: 640px) {
  .house-letterhead {
    grid-template-columns: 1fr;
  }
  .house-letterhead__actions {
    justify-content: flex-start;
  }
}

/* ── Tabs, as index-card dividers ───────────────────────────────── */
.house-tabs {
  display: flex;
  gap: 0.25rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid var(--color-paper-3);
  overflow-x: auto;
  scrollbar-width: none;
}
.house-tab {
  position: relative;
  flex-shrink: 0;
  padding: 0.55rem 1rem 0.5rem;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 6px 6px 0 0;
  background: none;
  color: var(--color-ink-muted);
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
}
.house-tab:hover {
  color: var(--color-ink);
}
.house-tab[aria-selected="true"] {
  margin-bottom: -1px;
  border-color: var(--color-paper-3);
  background: var(--color-paper);
  color: var(--color-ink);
}
.house-tab__count {
  margin-left: 0.4rem;
  color: var(--color-vermilion);
}

/* ── Cabinet layout: diagram left, sheet right ──────────────────── */
.house-cabinet {
  display: grid;
  grid-template-columns: minmax(18rem, 26rem) 1fr;
  gap: 2rem;
  padding-top: 1.75rem;
}
@media (max-width: 900px) {
  .house-cabinet {
    grid-template-columns: 1fr;
  }
}

/* ── The diagram ────────────────────────────────────────────────── */
.house-diagram {
  position: sticky;
  top: 1.25rem;
  align-self: start;
}
@media (max-width: 900px) {
  .house-diagram {
    position: static;
  }
}
.house-diagram__caption {
  margin: 0 0 0.75rem;
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-tree {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
/* Letterhead node */
.house-node {
  position: relative;
  display: block;
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease;
}
.house-node:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node[aria-current="true"] {
  border-color: var(--color-ink);
  box-shadow:
    inset 0 0 0 1px var(--color-ink),
    0 8px 18px -14px rgb(0 0 0 / 0.5);
}
.house-node__kind {
  display: block;
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-node__name {
  display: block;
  margin-top: 0.15rem;
  font: 700 1rem/1.2 var(--font-display);
}
.house-node__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}
.house-node--house {
  border-top: 4px solid var(--color-vermilion);
  background: linear-gradient(
    var(--color-paper),
    color-mix(in srgb, var(--color-paper) 92%, var(--color-vermilion) 3%)
  );
}
/* A collection is a cabinet drawer: brass label holder, pull. */
.house-drawer {
  position: relative;
  margin-left: 1.1rem;
}
.house-drawer::before {
  content: "";
  position: absolute;
  left: -0.75rem;
  top: -0.6rem;
  bottom: 1.2rem;
  border-left: 1px dashed var(--color-ink-muted);
  opacity: 0.6;
}
.house-node--collection {
  padding-left: 2.6rem;
  background: var(--color-paper-2);
  border-bottom-width: 3px;
}
.house-node--collection::before {
  /* the label holder */
  content: "";
  position: absolute;
  left: 0.75rem;
  top: 50%;
  width: 1.1rem;
  height: 0.7rem;
  transform: translateY(-50%);
  border: 1.5px solid var(--color-mustard);
  border-radius: 1px;
  background: color-mix(in srgb, var(--color-mustard) 12%, transparent);
}
.house-node--loose {
  border-style: dashed;
  background: transparent;
}
.house-node--loose::before {
  border-color: var(--color-ink-muted);
  background: none;
}
/* Folios are manila folders with a tab, standing in the drawer. */
.house-folders {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0.35rem 0 0.2rem 1.2rem;
}
.house-folder {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.6rem 0.4rem;
  margin-top: 0.35rem;
  border: 1px solid color-mix(in srgb, var(--color-mustard) 45%, var(--color-paper-3));
  border-radius: 0 3px 3px 3px;
  background: color-mix(in srgb, var(--color-paper) 82%, var(--color-mustard) 14%);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 140ms ease;
}
.house-folder::before {
  /* the tab */
  content: "";
  position: absolute;
  left: -1px;
  top: -0.4rem;
  width: 2.6rem;
  height: 0.4rem;
  border: inherit;
  border-bottom: 0;
  border-radius: 3px 3px 0 0;
  background: inherit;
}
.house-folder:hover {
  transform: translateX(2px);
}
.house-folder[aria-current="true"] {
  border-color: var(--color-ink);
}
.house-folder__name {
  font: 0.86rem/1.25 var(--font-display);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.house-folder__marks {
  display: flex;
  gap: 0.25rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-folder__empty {
  margin: 0.2rem 0 0;
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Chips: typed tags */
.house-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.05rem 0.4rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-soft);
  font: 0.6rem/1.5 var(--font-typewriter);
  letter-spacing: 0.04em;
  color: var(--color-ink-light);
}
.house-chip--must {
  border-color: color-mix(in srgb, var(--color-vermilion) 50%, transparent);
  color: var(--color-vermilion);
}

/* The legend under the tree: how the stack pours down. */
.house-legend {
  margin-top: 1.25rem;
  padding: 0.85rem 0.9rem;
  border: 1px dashed var(--color-paper-3);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--color-ink-light);
}
.house-legend dt {
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink);
}
.house-legend dd {
  margin: 0.1rem 0 0.55rem;
}
.house-legend dd:last-child {
  margin-bottom: 0;
}

/* ── The sheet in the platen ───────────────────────────────────── */
.house-sheet {
  position: relative;
  padding: 2rem 2.25rem 2.25rem;
  background: var(--color-editor-bg);
  border: 1px solid var(--color-paper-3);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 22px 40px -32px rgb(0 0 0 / 0.55);
  animation: house-sheet-in 260ms ease-out;
}
@keyframes house-sheet-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@media (max-width: 640px) {
  .house-sheet {
    padding: 1.25rem 1rem 1.5rem;
  }
}
.house-sheet__kicker {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}
.house-sheet__title {
  display: block;
  width: 100%;
  margin: 0.35rem 0 0.25rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--color-ink);
  font: 700 1.6rem/1.15 var(--font-display);
}
.house-sheet__title:focus {
  outline: none;
  box-shadow: 0 2px 0 var(--color-vermilion);
}
.house-sheet__lede {
  margin: 0 0 1.5rem;
  font-style: italic;
  color: var(--color-ink-light);
}
.house-section {
  margin-top: 1.75rem;
}
.house-section:first-of-type {
  margin-top: 0;
}
.house-section__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.35rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-ink);
}
.house-section__title {
  font: 0.68rem var(--font-typewriter);
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.house-section__note {
  font: italic 0.78rem var(--font-serif);
  color: var(--color-ink-muted);
}

/* Dossier fields: typed lines on a form. The source layer is stamped. */
.house-fields {
  display: flex;
  flex-direction: column;
}
.house-field {
  display: grid;
  grid-template-columns: 8.5rem 1fr;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
@media (max-width: 640px) {
  .house-field {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }
}
.house-field__label {
  padding-top: 0.3rem;
  font: 0.6rem var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-field__value {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 0;
}
.house-input {
  width: 100%;
  padding: 0.25rem 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--color-ink);
  font: 0.95rem/1.5 var(--font-typewriter);
  resize: none;
  field-sizing: content;
  min-height: 1.6rem;
}
.house-input::placeholder {
  color: var(--color-ink-muted);
  opacity: 0.55;
  font-style: italic;
}
.house-input:hover {
  border-bottom-color: var(--color-paper-3);
}
.house-input:focus {
  outline: none;
  border-bottom-color: var(--color-vermilion);
}
.house-input[readonly] {
  cursor: default;
  border-bottom-color: transparent;
}
.house-inherit {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  font: 0.72rem/1.4 var(--font-serif);
  color: var(--color-ink-muted);
}
.house-inherit s {
  opacity: 0.7;
}
/* A layer stamp — the rubber stamp each field carries. */
.house-stamp {
  display: inline-block;
  padding: 0 0.3rem;
  border: 1.25px solid currentColor;
  border-radius: 2px;
  font: 0.54rem/1.5 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transform: rotate(-2deg);
  mix-blend-mode: multiply;
}
.house-stamp--house {
  color: var(--color-vermilion);
}
.house-stamp--collection {
  color: var(--color-mustard);
}
.house-stamp--folio {
  color: var(--color-cobalt);
}
.house-stamp--amendment {
  color: var(--color-writer-note);
}
.house-stamp--charter {
  color: var(--color-sage);
}

/* The charter: numbered articles. */
.house-charter {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: article;
}
.house-article {
  counter-increment: article;
  display: grid;
  grid-template-columns: 2.4rem 1fr auto;
  gap: 0.5rem;
  align-items: start;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--color-paper-3);
}
.house-article::before {
  content: "Art. " counter(article);
  padding-top: 0.3rem;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-article__text {
  font: 0.92rem/1.5 var(--font-typewriter);
}
.house-article__controls {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.house-severity {
  padding: 0.05rem 0.4rem;
  border: 1.25px solid var(--color-paper-3);
  border-radius: 2px;
  background: none;
  font: 0.58rem/1.5 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
  cursor: pointer;
}
.house-severity[data-severity="must"] {
  border-color: var(--color-vermilion);
  color: var(--color-vermilion);
}
.house-remove {
  border: 0;
  background: none;
  color: var(--color-ink-muted);
  font-size: 0.75rem;
  cursor: pointer;
  opacity: 0.5;
}
.house-article:hover .house-remove,
.house-remove:focus-visible {
  opacity: 1;
}
.house-remove:hover {
  color: var(--color-vermilion);
}
.house-article--inherited {
  opacity: 0.8;
}
.house-article--inherited .house-article__text {
  color: var(--color-ink-light);
}
.house-new-article {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.5rem;
  margin-top: 0.75rem;
}
@media (max-width: 640px) {
  .house-new-article {
    grid-template-columns: 1fr auto;
  }
  .house-new-article .btn-press {
    grid-column: 1 / -1;
  }
}
.house-new-article input {
  padding: 0.45rem 0.6rem;
  border: 1px dashed var(--color-paper-3);
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font: 0.88rem var(--font-typewriter);
}
.house-new-article input:focus {
  outline: none;
  border-style: solid;
  border-color: var(--color-ink);
}

/* Members of a collection: folders to file in and out. */
.house-members {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
  gap: 0.5rem;
}
.house-member {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-paper);
  font: 0.85rem var(--font-display);
  cursor: pointer;
}
.house-member input {
  accent-color: var(--color-vermilion);
}
.house-member small {
  display: block;
  font: 0.58rem var(--font-typewriter);
  color: var(--color-ink-muted);
}

/* The model's copy: exactly what is sent. */
.house-carbon {
  margin: 0;
  padding: 1rem 1.1rem;
  border: 1px solid var(--color-paper-3);
  background: repeating-linear-gradient(
    var(--color-paper-soft) 0 1.55rem,
    var(--color-editor-line) 1.55rem calc(1.55rem + 1px)
  );
  color: color-mix(in srgb, var(--color-cobalt) 75%, var(--color-ink));
  font: 0.8rem/1.55rem var(--font-typewriter);
  white-space: pre-wrap;
  word-break: break-word;
}
.house-costs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.house-sheet__foot {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: space-between;
  align-items: center;
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid var(--color-paper-3);
}
.house-saved {
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.08em;
  color: var(--color-ink-muted);
}
.house-saved--error {
  color: var(--color-vermilion);
}

/* ── The register (ledger) ─────────────────────────────────────── */
.house-register {
  margin-top: 1.75rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-register__row {
  display: grid;
  grid-template-columns: 7.5rem 9rem 1fr;
  gap: 1rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--color-editor-line);
}
.house-register__row:last-child {
  border-bottom: 0;
}
@media (max-width: 720px) {
  .house-register__row {
    grid-template-columns: 1fr;
    gap: 0.3rem;
  }
}
.house-register__when {
  font: 0.66rem/1.5 var(--font-typewriter);
  color: var(--color-ink-muted);
}
.house-register__what {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  font-size: 0.86rem;
}
.house-register__diff {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font: 0.8rem/1.45 var(--font-typewriter);
}
.house-register__from {
  color: var(--color-ink-muted);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--color-vermilion) 60%, transparent);
}
.house-register__why {
  font: italic 0.8rem var(--font-serif);
  color: var(--color-ink-light);
}
/* An amendment is a slip pasted into the register. */
.house-register__row--amendment {
  background: color-mix(in srgb, var(--color-editor-bg) 88%, var(--color-writer-note) 6%);
  box-shadow: inset 3px 0 0 var(--color-writer-note);
}
.house-register__filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 1.5rem;
}
.house-filter {
  padding: 0.2rem 0.6rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 999px;
  background: none;
  color: var(--color-ink-muted);
  font: 0.62rem var(--font-typewriter);
  letter-spacing: 0.06em;
  cursor: pointer;
}
.house-filter[aria-pressed="true"] {
  border-color: var(--color-ink);
  color: var(--color-ink);
  background: var(--color-paper);
}

.house-empty {
  padding: 2.5rem 1rem;
  text-align: center;
  color: var(--color-ink-muted);
  font-style: italic;
}

/* ── The engine room (diagnostics) ─────────────────────────────── */
.house-engine {
  margin-top: 1.75rem;
  display: grid;
  gap: 1.25rem;
}
.house-gauges {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(10.5rem, 1fr));
  gap: 0.6rem;
}
.house-gauge {
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
}
.house-gauge__label {
  font: 0.56rem var(--font-typewriter);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.house-gauge__value {
  margin-top: 0.2rem;
  font: 700 1.2rem/1.2 var(--font-display);
  font-variant-numeric: tabular-nums;
}
.house-gauge__hint {
  margin-top: 0.15rem;
  font-size: 0.72rem;
  color: var(--color-ink-muted);
}
.house-weights {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.house-weight {
  display: grid;
  grid-template-columns: 8rem 1fr 3rem;
  gap: 0.6rem;
  align-items: center;
  font: 0.7rem var(--font-typewriter);
}
.house-weight__bar {
  position: relative;
  height: 6px;
  background: var(--color-paper-2);
}
.house-weight__bar span {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--color-cobalt);
}
.house-weight__bar::after {
  /* the neutral line at 1.0 */
  content: "";
  position: absolute;
  left: 55.5%;
  top: -3px;
  bottom: -3px;
  border-left: 1px solid var(--color-ink-muted);
}
.house-log {
  border: 1px solid var(--color-paper-3);
  background: var(--color-editor-bg);
  max-height: 32rem;
  overflow: auto;
}
.house-log__row {
  display: grid;
  grid-template-columns: 5.5rem 5rem 1fr;
  gap: 0.75rem;
  padding: 0.4rem 0.8rem;
  border-bottom: 1px solid var(--color-editor-line);
  font: 0.7rem/1.5 var(--font-typewriter);
}
.house-log__row summary {
  cursor: pointer;
  list-style: none;
}
.house-log__row summary::-webkit-details-marker {
  display: none;
}
.house-log__kind {
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.house-log__kind--mode {
  color: var(--color-cobalt);
}
.house-log__kind--jev {
  color: var(--color-writer-note);
}
.house-log__kind--surface,
.house-log__kind--item {
  color: var(--color-sage);
}
.house-log__kind--focus {
  color: var(--color-mustard);
}
.house-log__kind--error {
  color: var(--color-vermilion);
}
.house-log pre {
  margin: 0.4rem 0 0.2rem;
  padding: 0.5rem;
  background: var(--color-paper-2);
  font-size: 0.66rem;
  white-space: pre-wrap;
  word-break: break-word;
}

@media (prefers-reduced-motion: reduce) {
  .house-sheet,
  .house-node,
  .house-folder {
    animation: none;
    transition: none;
  }
}

input.content:
/**
 * The House — where a writer sees, and shapes, everything that tells Twyne
 * what their writing is for.
 *
 *   Cabinet      the hierarchy, drawn as a filing cabinet: the House on its
 *                letterhead, collections as drawers, folios as folders. Pick
 *                any of them to open its sheet — its dossier, its charter,
 *                and exactly what the models are handed.
 *   Register     every change to that context, newest first: who or what
 *                made it, from what, to what, and why.
 *   Engine room  for whoever is tuning the plumbing: what the flow reader has
 *                learned, the thresholds it derived, and its decision log.
 */
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link, useLocation, type DocumentHead } from "@qwik.dev/router";
import "../../components/house/house.css";
import type { Folio, ProjectBrief } from "../../types";
import {
  loadActiveFolioIdFromIdb,
  loadAllBriefsFromIdb,
  loadFoliosFromIdb,
  loadMetaFromIdb,
} from "../../utils/idb";
import { loadBriefEditions, type BriefEdition } from "../../utils/brief-history";
import {
  assembleContextStack,
  collectionForFolio,
  contextForModels,
  DOSSIER_FIELD_LABELS,
  DOSSIER_FIELDS,
  emptyHouseState,
  INHERITABLE_FIELDS,
  LAYER_LABELS,
  LEDGER_SOURCE_LABELS,
  type CharterItem,
  type CharterScope,
  type ContextLayer,
  type DossierField,
  type HouseState,
  type LedgerEntry,
} from "../../utils/house-model";
import {
  createCollection,
  deleteCollection,
  HOUSE_CHANGED_EVENT,
  loadHouseState,
  removeCharterItem,
  setFolioCollection,
  setHouseField,
  setHouseName,
  updateCollection,
  upsertCharterItem,
  type HouseChangedDetail,
} from "../../utils/house-store";
import {
  kindWeight,
  normalizeProfile,
  thresholdsFor,
  writingHours,
  type FlowProfile,
} from "../../utils/flow-profile";
import { KIND_LABELS, type FlowItemKind } from "../../utils/flow-items";
import {
  clearFlowDiagnostics,
  FLOW_DIAGNOSTICS_EVENT,
  loadFlowDiagnostics,
  type DiagnosticEntry,
} from "../../utils/flow-diagnostics";

type Tab = "cabinet" | "register" | "engine";
type Selection =
  | { kind: "house" }
  | { kind: "collection"; id: string }
  | { kind: "folio"; id: string };
type RegisterFilter = "all" | "amendment" | "dossier" | "charter" | "collection";

interface HouseStore {
  loaded: boolean;
  tab: Tab;
  selection: Selection;
  house: HouseState;
  folios: Folio[];
  briefs: Record<string, ProjectBrief>;
  editions: Record<string, BriefEdition[]>;
  activeFolioId: string | null;
  profile: FlowProfile | null;
  log: DiagnosticEntry[];
  status: string;
  error: boolean;
  newArticle: string;
  newSeverity: "must" | "prefer";
  confirmDissolve: boolean;
  filter: RegisterFilter;
}

/* ── Module helpers (kept out of the component so handlers can use them) ── */

async function commit(state: HouseStore, work: Promise<HouseState>, done = "Filed.") {
  try {
    state.house = await work;
    state.status = done;
    state.error = false;
  } catch (error) {
    state.status =
      error instanceof Error ? error.message : "That could not be saved on this device.";
    state.error = true;
  }
}

/** Typewriter date stamp: 29 SEPT 2026 · 14:05. */
function stamp(ts: number): string {
  const d = new Date(ts);
  const day = d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
  const time = d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  return `${day} · ${time}`.toUpperCase();
}

function seconds(ms: number): string {
  return ms >= 60_000 ? `${Math.round(ms / 6_000) / 10} min` : `${Math.round(ms / 1000)} s`;
}

function hourLabel(hour: number): string {
  return new Date(2000, 0, 1, hour).toLocaleTimeString(undefined, { hour: "numeric" });
}

function ownerName(state: HouseStore, ownerRef: string): string {
  if (ownerRef === "house") return state.house.house.name || "The House";
  const collection = state.house.collections.find((c) => c.id === ownerRef);
  if (collection) return collection.name;
  return state.folios.find((f) => f.id === ownerRef)?.name ?? "A folio";
}

function matchesFilter(entry: LedgerEntry, filter: RegisterFilter): boolean {
  switch (filter) {
    case "amendment":
      return entry.source === "amendment";
    case "dossier":
      return entry.layer !== "charter" && !!entry.field && entry.source !== "amendment";
    case "charter":
      return entry.layer === "charter";
    case "collection":
      return entry.layer === "collection";
    default:
      return true;
  }
}

function fieldLabel(field?: string): string {
  if (!field) return "";
  if (field === "must" || field === "prefer") return field === "must" ? "Article (must)" : "Article (prefer)";
  return DOSSIER_FIELD_LABELS[field as DossierField] ?? field;
}

const LEGEND: Array<[string, string]> = [
  ["The House", "You. Defaults every piece inherits, and the house charter."],
  ["Collection", "A series — a column, a book's chapters, a newsletter. Narrows the House for its folios."],
  ["Folio", "One piece. Its dossier has the last word on what it is for."],
  ["Charter", "Standards that follow you. Every article from above still applies below."],
  ["Edition · Revision", "An edition changes what the words are for; a revision changes the words."],
  ["Amendment", "A dossier change the draft itself proposed, and you filed."],
];

export default component$(() => {
  const location = useLocation();
  const state = useStore<HouseStore>({
    loaded: false,
    tab: "cabinet",
    selection: { kind: "house" },
    house: emptyHouseState(),
    folios: [],
    briefs: {},
    editions: {},
    activeFolioId: null,
    profile: null,
    log: [],
    status: "",
    error: false,
    newArticle: "",
    newSeverity: "prefer",
    confirmDissolve: false,
    filter: "all",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const params = location.url.searchParams;
    const [house, folios, briefs, active, profile, log] = await Promise.all([
      loadHouseState(),
      loadFoliosFromIdb(),
      loadAllBriefsFromIdb(),
      loadActiveFolioIdFromIdb(),
      loadMetaFromIdb<FlowProfile>("flow-profile"),
      loadFlowDiagnostics(),
    ]);
    state.house = house;
    state.folios = [...folios].sort((a, b) => b.updatedAt - a.updatedAt);
    state.briefs = Object.fromEntries(briefs.map((b) => [b.folioId, b.brief]));
    state.activeFolioId = active;
    state.profile = normalizeProfile(profile);
    state.log = [...log].reverse();
    const editions = await Promise.all(folios.map((f) => loadBriefEditions(f.id)));
    state.editions = Object.fromEntries(folios.map((f, i) => [f.id, editions[i]]));

    const requested = params.get("folio");
    const tab = params.get("tab");
    if (tab === "register" || tab === "engine") state.tab = tab;
    if (requested && folios.some((f) => f.id === requested))
      state.selection = { kind: "folio", id: requested };
    else if (active && folios.some((f) => f.id === active))
      state.selection = { kind: "folio", id: active };
    state.loaded = true;

    const onHouse = (event: Event) => {
      state.house = (event as CustomEvent<HouseChangedDetail>).detail.state;
    };
    const onLog = (event: Event) => {
      state.log = [(event as CustomEvent<DiagnosticEntry>).detail, ...state.log].slice(0, 300);
    };
    window.addEventListener(HOUSE_CHANGED_EVENT, onHouse);
    window.addEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    cleanup(() => {
      window.removeEventListener(HOUSE_CHANGED_EVENT, onHouse);
      window.removeEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    });
  });

  const select = $((selection: Selection) => {
    state.selection = selection;
    state.newArticle = "";
    state.newSeverity = "prefer";
    state.confirmDissolve = false;
    state.status = "";
  });

  const addArticle = $(async (scope: CharterScope, ownerRef: string) => {
    const text = state.newArticle.trim();
    if (!text) return;
    await commit(
      state,
      upsertCharterItem({ scope, ownerRef, text, severity: state.newSeverity, kind: "other" }),
      "Article added to the charter.",
    );
    if (!state.error) state.newArticle = "";
  });

  const founding = $(async () => {
    const before = new Set(state.house.collections.map((c) => c.id));
    await commit(state, createCollection("New collection"), "Collection founded.");
    const fresh = state.house.collections.find((c) => !before.has(c.id));
    if (fresh) await select({ kind: "collection", id: fresh.id });
  });

  const exportEngine = $(() => {
    const blob = new Blob(
      [
        JSON.stringify(
          { exportedAt: new Date().toISOString(), profile: state.profile, log: state.log, house: state.house },
          null,
          2,
        ),
      ],
      { type: "application/json" },
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `twyne-engine-room-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });

  /* ── Pieces of the page ─────────────────────────────────────── */

  const houseName = state.house.house.name;
  const collections = state.house.collections;
  const looseFolios = state.folios.filter((f) => !collectionForFolio(state.house, f.id));
  const sel = state.selection;

  const layerStamp = (layer: ContextLayer | "charter" | null) =>
    layer ? (
      <span class={`house-stamp house-stamp--${layer}`}>
        {layer === "charter" ? "Charter" : LAYER_LABELS[layer]}
      </span>
    ) : null;

  const folder = (folio: Folio) => {
    const brief = state.briefs[folio.id];
    const editions = state.editions[folio.id]?.length ?? 0;
    const articles = state.house.charter.filter((c) => c.ownerRef === folio.id).length;
    return (
      <button
        key={folio.id}
        type="button"
        class="house-folder"
        aria-current={sel.kind === "folio" && sel.id === folio.id ? "true" : undefined}
        onClick$={() => select({ kind: "folio", id: folio.id })}
      >
        <span class="house-folder__name">{folio.name || "Untitled"}</span>
        <span class="house-folder__marks">
          {brief ? <span title="Dossier filed">D</span> : <span title="No dossier">—</span>}
          {editions > 0 && <span title={`${editions} earlier editions`}>{editions}ed</span>}
          {articles > 0 && <span title="Charter articles">§{articles}</span>}
          {state.activeFolioId === folio.id && <span title="Open on the desk">●</span>}
        </span>
      </button>
    );
  };

  const article = (item: CharterItem, inherited: boolean) => (
    <li key={item.id} class={["house-article", { "house-article--inherited": inherited }]}>
      {inherited ? (
        <span class="house-article__text">{item.text}</span>
      ) : (
        <input
          class="house-input house-article__text"
          value={item.text}
          aria-label="Charter article"
          onChange$={(_, el) => {
            const text = el.value.trim();
            if (!text || text === item.text) return;
            void commit(state, upsertCharterItem({ ...item, text }), "Article amended.");
          }}
        />
      )}
      <span class="house-article__controls">
        {inherited ? (
          layerStamp(item.scope === "house" ? "house" : "collection")
        ) : null}
        <button
          type="button"
          class="house-severity"
          data-severity={item.severity}
          disabled={inherited}
          title={
            inherited
              ? "Set where this article was written"
              : item.severity === "must"
                ? "A requirement. Click to make it a preference."
                : "A preference. Click to make it a requirement."
          }
          onClick$={() =>
            commit(
              state,
              upsertCharterItem({ ...item, severity: item.severity === "must" ? "prefer" : "must" }),
              "Article amended.",
            )
          }
        >
          {item.severity}
        </button>
        {!inherited && (
          <button
            type="button"
            class="house-remove"
            aria-label={`Withdraw: ${item.text}`}
            title="Withdraw this article"
            onClick$={() => commit(state, removeCharterItem(item.id), "Article withdrawn.")}
          >
            ✕
          </button>
        )}
      </span>
    </li>
  );

  const charterSection = (scope: CharterScope, ownerRef: string, inherited: CharterItem[]) => {
    const own = state.house.charter
      .filter((c) => c.ownerRef === ownerRef)
      .sort((a, b) => a.order - b.order);
    return (
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Charter</h3>
          <span class="house-section__note">
            {scope === "house"
              ? "Standards for everything you write"
              : scope === "collection"
                ? "Standards for every piece in this collection"
                : "Standards for this piece alone"}
          </span>
        </header>
        {inherited.length + own.length === 0 ? (
          <p class="house-folder__empty">
            No articles yet. Twyne checks your draft against each one on a pause, and says so in
            the margin when a passage breaks it.
          </p>
        ) : (
          <ol class="house-charter">
            {inherited.map((item) => article(item, true))}
            {own.map((item) => article(item, false))}
          </ol>
        )}
        <form
          class="house-new-article"
          preventdefault:submit
          onSubmit$={() => addArticle(scope, ownerRef)}
        >
          <input
            value={state.newArticle}
            placeholder={
              scope === "house"
                ? "e.g. Cite a primary source for every statistic"
                : scope === "collection"
                  ? "e.g. Every issue opens on a scene, not a thesis"
                  : "e.g. Stay under 1,200 words"
            }
            aria-label="New charter article"
            onInput$={(_, el) => {
              state.newArticle = el.value;
            }}
          />
          <button
            type="button"
            class="house-severity"
            data-severity={state.newSeverity}
            onClick$={() => {
              state.newSeverity = state.newSeverity === "must" ? "prefer" : "must";
            }}
            title="Requirement or preference"
          >
            {state.newSeverity}
          </button>
          <button type="submit" class="btn-press" disabled={!state.newArticle.trim()}>
            Add article
          </button>
        </form>
      </section>
    );
  };

  const saveLine = state.status ? (
    <span class={["house-saved", { "house-saved--error": state.error }]} role="status">
      {state.status}
    </span>
  ) : (
    <span class="house-saved">Changes are filed as you make them.</span>
  );

  /* ── Sheets ─────────────────────────────────────────────────── */

  const houseSheet = () => (
    <article class="house-sheet" key="house">
      <p class="house-sheet__kicker">The House</p>
      <h2 class="house-sheet__title">House defaults</h2>
      <p class="house-sheet__lede">
        Set these once. Every piece inherits them unless its collection, or its own dossier, says
        otherwise.
      </p>
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Dossier</h3>
          <span class="house-section__note">Inherited by every folio</span>
        </header>
        <div class="house-fields">
          {INHERITABLE_FIELDS.map((field) => (
            <label key={field} class="house-field">
              <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
              <span class="house-field__value">
                <textarea
                  class="house-input"
                  rows={1}
                  value={state.house.house.dossier[field] ?? ""}
                  placeholder="Leave blank to let each piece decide"
                  onChange$={(_, el) =>
                    commit(state, setHouseField(field, el.value), `${DOSSIER_FIELD_LABELS[field]} set for the House.`)
                  }
                />
              </span>
            </label>
          ))}
        </div>
      </section>
      {charterSection("house", "house", [])}
      <footer class="house-sheet__foot">{saveLine}</footer>
    </article>
  );

  const collectionSheet = (id: string) => {
    const collection = collections.find((c) => c.id === id);
    if (!collection) return houseSheet();
    const inherited = state.house.charter.filter((c) => c.ownerRef === "house");
    return (
      <article class="house-sheet" key={`collection-${id}`}>
        <p class="house-sheet__kicker">Collection</p>
        <input
          class="house-sheet__title"
          value={collection.name}
          aria-label="Collection name"
          onChange$={(_, el) => commit(state, updateCollection(id, { name: el.value }), "Renamed.")}
        />
        <textarea
          class="house-input house-sheet__lede"
          rows={1}
          value={collection.description}
          placeholder="What binds this series together?"
          aria-label="What binds this series together"
          onChange$={(_, el) => commit(state, updateCollection(id, { description: el.value }))}
        />

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier</h3>
            <span class="house-section__note">Narrows the House for these folios</span>
          </header>
          <div class="house-fields">
            {INHERITABLE_FIELDS.map((field) => {
              const fromHouse = state.house.house.dossier[field]?.trim();
              return (
                <label key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    <textarea
                      class="house-input"
                      rows={1}
                      value={collection.dossier[field] ?? ""}
                      placeholder={fromHouse ? `Inherits: ${fromHouse}` : "Leave blank to let each piece decide"}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          updateCollection(id, { field: { name: field, value: el.value } }),
                          `${DOSSIER_FIELD_LABELS[field]} set for ${collection.name}.`,
                        )
                      }
                    />
                    {fromHouse && collection.dossier[field]?.trim() && (
                      <span class="house-inherit">
                        {layerStamp("house")} overrides <s>{fromHouse}</s>
                      </span>
                    )}
                  </span>
                </label>
              );
            })}
          </div>
        </section>

        {charterSection("collection", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Folios in this collection</h3>
            <span class="house-section__note">A folio sits in one drawer at a time</span>
          </header>
          {state.folios.length === 0 ? (
            <p class="house-folder__empty">No folios yet.</p>
          ) : (
            <div class="house-members">
              {state.folios.map((folio) => {
                const other = collectionForFolio(state.house, folio.id);
                const inHere = other?.id === id;
                return (
                  <label key={folio.id} class="house-member">
                    <input
                      type="checkbox"
                      checked={inHere}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          setFolioCollection(folio.id, el.checked ? id : null),
                          el.checked ? `Filed under ${collection.name}.` : "Taken out of the collection.",
                        )
                      }
                    />
                    <span>
                      {folio.name || "Untitled"}
                      {other && !inHere && <small>now in {other.name}</small>}
                    </span>
                  </label>
                );
              })}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.confirmDissolve ? (
            <span style={{ display: "flex", gap: "0.5rem" }}>
              <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = false)}>
                Keep it
              </button>
              <button
                type="button"
                class="btn-press"
                onClick$={async () => {
                  await commit(state, deleteCollection(id), "Collection dissolved; its folios are loose.");
                  await select({ kind: "house" });
                }}
              >
                Dissolve
              </button>
            </span>
          ) : (
            <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = true)}>
              Dissolve collection…
            </button>
          )}
        </footer>
      </article>
    );
  };

  const folioSheet = (id: string) => {
    const folio = state.folios.find((f) => f.id === id);
    if (!folio) return houseSheet();
    const brief = state.briefs[id] ?? null;
    const stack = assembleContextStack(state.house, id, brief);
    const models = contextForModels(stack);
    const inherited = stack.charter.filter((c) => c.inherited);
    const editions = state.editions[id] ?? [];
    return (
      <article class="house-sheet" key={`folio-${id}`}>
        <p class="house-sheet__kicker">
          Folio{stack.collection ? ` · ${stack.collection.name}` : ""}
        </p>
        <h2 class="house-sheet__title">{folio.name || "Untitled"}</h2>
        <p class="house-sheet__lede">
          What this piece is for, and where each part of that came from.
        </p>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier, as the models see it</h3>
            <Link href={`/dossier/refine/?folio=${encodeURIComponent(id)}`} class="flow-link">
              Refine the dossier →
            </Link>
          </header>
          <div class="house-fields">
            {DOSSIER_FIELDS.map((field) => {
              const entry = stack.fields[field];
              return (
                <div key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    {entry.value ? (
                      <span class="house-input" style={{ whiteSpace: "pre-wrap" }}>
                        {entry.value}
                      </span>
                    ) : (
                      <span class="house-folder__empty">Nothing set at any level.</span>
                    )}
                    {(entry.layer || entry.shadowed.length > 0) && (
                      <span class="house-inherit">
                        {layerStamp(entry.layer)}
                        {entry.shadowed.map((s) => (
                          <span key={s.layer}>
                            overrides {LAYER_LABELS[s.layer].toLowerCase()} <s>{s.value}</s>
                          </span>
                        ))}
                      </span>
                    )}
                  </span>
                </div>
              );
            })}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Filed under</h3>
          </header>
          <select
            class="btn-paper"
            value={stack.collection?.id ?? ""}
            aria-label="Collection"
            onChange$={(_, el) =>
              commit(
                state,
                setFolioCollection(id, el.value || null),
                el.value ? "Filed under the collection." : "Now a loose folio.",
              )
            }
          >
            <option value="">Loose — no collection</option>
            {collections.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </section>

        {charterSection("folio", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">What the models read</h3>
            <span class="house-section__note">Exactly this, ahead of every judgement</span>
          </header>
          {models.text ? (
            <pre class="house-carbon">{models.text}</pre>
          ) : (
            <p class="house-folder__empty">Nothing yet — the models see only the draft.</p>
          )}
          <div class="house-costs">
            {models.layers.map((l) => (
              <span key={l.layer} class="house-chip">
                {l.layer === "charter" ? "Charter" : LAYER_LABELS[l.layer]} · ≈{l.tokens} tokens
              </span>
            ))}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Editions</h3>
            <span class="house-section__note">
              {editions.length
                ? `${editions.length} earlier ${editions.length === 1 ? "edition" : "editions"} of this dossier`
                : "The dossier has not changed since it was filed"}
            </span>
          </header>
          {editions.length > 0 && (
            <div class="house-register" style={{ marginTop: 0 }}>
              {editions.slice(0, 5).map((edition) => (
                <div
                  key={edition.id}
                  class={[
                    "house-register__row",
                    { "house-register__row--amendment": edition.source === "amendment" },
                  ]}
                >
                  <span class="house-register__when">{stamp(edition.savedAt)}</span>
                  <span class="house-register__what">
                    {edition.source ? LEDGER_SOURCE_LABELS[edition.source] : "Superseded"}
                  </span>
                  <span class="house-register__diff">
                    <span>{edition.brief.answers.goal || edition.brief.answers.workingTitle}</span>
                    {edition.reason && <span class="house-register__why">{edition.reason}</span>}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.activeFolioId === id ? (
            <Link href="/editor/" class="btn-press">
              Back to the desk
            </Link>
          ) : null}
        </footer>
      </article>
    );
  };

  /* ── Tabs ───────────────────────────────────────────────────── */

  const cabinet = (
    <div class="house-cabinet">
      <nav class="house-diagram" aria-label="The House, its collections and folios">
        <p class="house-diagram__caption">The cabinet</p>
        <div class="house-tree">
          <button
            type="button"
            class="house-node house-node--house"
            aria-current={sel.kind === "house" ? "true" : undefined}
            onClick$={() => select({ kind: "house" })}
          >
            <span class="house-node__kind">The House</span>
            <span class="house-node__name">{houseName || "Your house"}</span>
            <span class="house-node__meta">
              <span class="house-chip">
                {Object.values(state.house.house.dossier).filter((v) => v?.trim()).length} defaults
              </span>
              <span class="house-chip">
                §{state.house.charter.filter((c) => c.ownerRef === "house").length} house charter
              </span>
            </span>
          </button>

          {collections.map((collection) => (
            <div key={collection.id} class="house-drawer">
              <button
                type="button"
                class="house-node house-node--collection"
                aria-current={sel.kind === "collection" && sel.id === collection.id ? "true" : undefined}
                onClick$={() => select({ kind: "collection", id: collection.id })}
              >
                <span class="house-node__kind">Collection</span>
                <span class="house-node__name">{collection.name}</span>
                <span class="house-node__meta">
                  <span class="house-chip">
                    {collection.folioIds.length} {collection.folioIds.length === 1 ? "folio" : "folios"}
                  </span>
                  {state.house.charter.some((c) => c.ownerRef === collection.id) && (
                    <span class="house-chip">
                      §{state.house.charter.filter((c) => c.ownerRef === collection.id).length}
                    </span>
                  )}
                </span>
              </button>
              <div class="house-folders">
                {collection.folioIds
                  .map((fid) => state.folios.find((f) => f.id === fid))
                  .filter((f): f is Folio => !!f)
                  .map(folder)}
                {collection.folioIds.length === 0 && (
                  <p class="house-folder__empty">Empty drawer — file folios from its sheet.</p>
                )}
              </div>
            </div>
          ))}

          <div class="house-drawer">
            <div class="house-node house-node--collection house-node--loose" aria-hidden="true">
              <span class="house-node__kind">Loose folios</span>
              <span class="house-node__name">Not in a collection</span>
            </div>
            <div class="house-folders">
              {looseFolios.map(folder)}
              {looseFolios.length === 0 && state.loaded && (
                <p class="house-folder__empty">Every folio is filed.</p>
              )}
            </div>
          </div>

          <button type="button" class="btn-paper" onClick$={founding}>
            + Found a collection
          </button>
        </div>

        <dl class="house-legend">
          {LEGEND.map(([term, meaning]) => (
            <div key={term}>
              <dt>{term}</dt>
              <dd>{meaning}</dd>
            </div>
          ))}
        </dl>
      </nav>

      {sel.kind === "house"
        ? houseSheet()
        : sel.kind === "collection"
          ? collectionSheet(sel.id)
          : folioSheet(sel.id)}
    </div>
  );

  const entries = state.house.ledger.filter((e) => matchesFilter(e, state.filter));
  const register = (
    <div>
      <div class="house-register__filters" role="group" aria-label="Filter the register">
        {(
          [
            ["all", "Everything"],
            ["amendment", "Amendments"],
            ["dossier", "Dossiers"],
            ["charter", "Charters"],
            ["collection", "Collections"],
          ] as const
        ).map(([value, label]) => (
          <button
            key={value}
            type="button"
            class="house-filter"
            aria-pressed={state.filter === value}
            onClick$={() => (state.filter = value)}
          >
            {label}
          </button>
        ))}
      </div>
      {entries.length === 0 ? (
        <p class="house-empty">
          The register is empty. It fills as dossiers are filed, refined and amended, and as
          charters change.
        </p>
      ) : (
        <div class="house-register">
          {entries.slice(0, 200).map((entry) => (
            <div
              key={entry.id}
              class={[
                "house-register__row",
                { "house-register__row--amendment": entry.source === "amendment" },
              ]}
            >
              <span class="house-register__when">{stamp(entry.at)}</span>
              <span class="house-register__what">
                <strong>{ownerName(state, entry.ownerRef)}</strong>
                <span>
                  {layerStamp(entry.layer === "charter" ? "charter" : entry.source === "amendment" ? "amendment" : entry.layer)}
                </span>
              </span>
              <span class="house-register__diff">
                <span class="house-section__note" style={{ fontStyle: "normal" }}>
                  {LEDGER_SOURCE_LABELS[entry.source]}
                  {entry.field ? ` — ${fieldLabel(entry.field)}` : ""}
                </span>
                {entry.from && <span class="house-register__from">{entry.from}</span>}
                {entry.to && <span>{entry.to}</span>}
                {entry.reason && <span class="house-register__why">{entry.reason}</span>}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const profile = state.profile;
  const t = profile ? thresholdsFor(profile) : null;
  const kinds = Object.keys(KIND_LABELS) as FlowItemKind[];
  const engine = (
    <div class="house-engine">
      <p class="house-sheet__lede" style={{ margin: 0 }}>
        What the flow reader has learned about how you write, the thresholds it derived from
        that, and every decision it made — for tuning the plumbing. Only rhythms and reactions are
        recorded here, never your words.
      </p>
      {profile && t && (
        <div class="house-gauges">
          {[
            ["Pauses learned", String(profile.pauses.length), profile.pauses.length >= 12 ? "Thresholds fitted to you" : "Defaults until 12"],
            ["Stuck after", seconds(t.stuckPauseMs), "a pause after circling"],
            ["Focus after", seconds(t.flowMs), "of steady writing"],
            ["Focus ends after", seconds(t.exitPauseMs), "a pause this long"],
            ["Times in flow", String(profile.flowEntries.length), "confirmed runs"],
            ["Hand overrides", String(profile.overrides), "you left focus yourself"],
            [
              "Usual hours",
              writingHours(profile).map(hourLabel).join(", ") || "—",
              "when you write most",
            ],
          ].map(([label, value, hint]) => (
            <div key={label} class="house-gauge">
              <div class="house-gauge__label">{label}</div>
              <div class="house-gauge__value">{value}</div>
              <div class="house-gauge__hint">{hint}</div>
            </div>
          ))}
        </div>
      )}

      {profile && (
        <section class="house-sheet" style={{ animation: "none" }}>
          <header class="house-section__head">
            <h3 class="house-section__title">What helps you</h3>
            <span class="house-section__note">Weight 1.0 is neutral; used kinds rise, waved-away kinds sink</span>
          </header>
          <div class="house-weights">
            {kinds.map((kind) => {
              const w = kindWeight(profile, kind);
              const s = profile.kinds[kind];
              return (
                <div key={kind} class="house-weight" title={s ? `${s.shown} shown · ${s.engaged} used · ${s.dismissed} set aside` : "Not seen yet"}>
                  <span>{KIND_LABELS[kind]}</span>
                  <span class="house-weight__bar">
                    <span style={{ width: `${(w / 1.8) * 100}%` }} />
                  </span>
                  <span>{w.toFixed(2)}</span>
                </div>
              );
            })}
          </div>
        </section>
      )}

      <section>
        <header class="house-section__head">
          <h3 class="house-section__title">Decision log</h3>
          <span style={{ display: "flex", gap: "0.5rem" }}>
            <button type="button" class="btn-paper" onClick$={exportEngine}>
              Export JSON
            </button>
            <button
              type="button"
              class="btn-paper"
              onClick$={async () => {
                await clearFlowDiagnostics();
                state.log = [];
              }}
            >
              Clear
            </button>
          </span>
        </header>
        {state.log.length === 0 ? (
          <p class="house-empty">
            Nothing logged yet. Write for a while on the desk and the reader's decisions appear
            here as they happen.
          </p>
        ) : (
          <div class="house-log">
            {state.log.map((entry) => (
              <details key={entry.id} class="house-log__row">
                <summary style={{ display: "contents" }}>
                  <span class="house-register__when">
                    {new Date(entry.at).toLocaleTimeString()}
                  </span>
                  <span class={`house-log__kind house-log__kind--${entry.kind}`}>{entry.kind}</span>
                  <span>{entry.summary}</span>
                </summary>
                {entry.detail && (
                  <pre style={{ gridColumn: "1 / -1" }}>{JSON.stringify(entry.detail, null, 2)}</pre>
                )}
              </details>
            ))}
          </div>
        )}
      </section>
    </div>
  );

  return (
    <div class="house">
      <div class="house__inner">
        <header class="house-letterhead">
          <div>
            <p class="house-letterhead__eyebrow">Maison d'édition</p>
            <input
              class="house-letterhead__name"
              value={houseName}
              placeholder="Name your house"
              aria-label="The name of your house"
              onChange$={(_, el) => commit(state, setHouseName(el.value), "The letterhead is reset.")}
            />
            <p class="house-letterhead__motto">
              Everything that tells Twyne what your writing is for — and how it has changed.
            </p>
          </div>
          <div class="house-letterhead__actions">
            <Link href="/library/" class="btn-paper">
              Library
            </Link>
            <Link href="/editor/" class="btn-press">
              ← The desk
            </Link>
          </div>
        </header>

        <div class="house-tabs" role="tablist" aria-label="The House">
          {(
            [
              ["cabinet", "The cabinet", null],
              ["register", "The register", state.house.ledger.length || null],
              ["engine", "Engine room", null],
            ] as const
          ).map(([tab, label, count]) => (
            <button
              key={tab}
              type="button"
              role="tab"
              class="house-tab"
              aria-selected={state.tab === tab}
              onClick$={() => (state.tab = tab)}
            >
              {label}
              {count ? <span class="house-tab__count">{count}</span> : null}
            </button>
          ))}
        </div>

        {!state.loaded ? (
          <p class="house-empty">Opening the cabinet…</p>
        ) : state.tab === "cabinet" ? (
          cabinet
        ) : state.tab === "register" ? (
          register
        ) : (
          engine
        )}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "The House · Twyne",
  meta: [
    {
      name: "description",
      content: "Your house, its collections, dossiers and charters — everything that tells Twyne what your writing is for.",
    },
  ],
};

toolu_01RTkG4hy8d45VnXFiXMvtLM.content:
/**
 * The House — where a writer sees, and shapes, everything that tells Twyne
 * what their writing is for.
 *
 *   Cabinet      the hierarchy, drawn as a filing cabinet: the House on its
 *                letterhead, collections as drawers, folios as folders. Pick
 *                any of them to open its sheet — its dossier, its charter,
 *                and exactly what the models are handed.
 *   Register     every change to that context, newest first: who or what
 *                made it, from what, to what, and why.
 *   Engine room  for whoever is tuning the plumbing: what the flow reader has
 *                learned, the thresholds it derived, and its decision log.
 */
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link, useLocation, type DocumentHead } from "@qwik.dev/router";
import "../../components/house/house.css";
import type { Folio, ProjectBrief } from "../../types";
import {
  loadActiveFolioIdFromIdb,
  loadAllBriefsFromIdb,
  loadFoliosFromIdb,
  loadMetaFromIdb,
} from "../../utils/idb";
import { loadBriefEditions, type BriefEdition } from "../../utils/brief-history";
import {
  assembleContextStack,
  collectionForFolio,
  contextForModels,
  DOSSIER_FIELD_LABELS,
  DOSSIER_FIELDS,
  emptyHouseState,
  INHERITABLE_FIELDS,
  LAYER_LABELS,
  LEDGER_SOURCE_LABELS,
  type CharterItem,
  type CharterScope,
  type ContextLayer,
  type DossierField,
  type HouseState,
  type LedgerEntry,
} from "../../utils/house-model";
import {
  createCollection,
  deleteCollection,
  HOUSE_CHANGED_EVENT,
  loadHouseState,
  removeCharterItem,
  setFolioCollection,
  setHouseField,
  setHouseName,
  updateCollection,
  upsertCharterItem,
  type HouseChangedDetail,
} from "../../utils/house-store";
import {
  kindWeight,
  normalizeProfile,
  thresholdsFor,
  writingHours,
  type FlowProfile,
} from "../../utils/flow-profile";
import { KIND_LABELS, type FlowItemKind } from "../../utils/flow-items";
import {
  clearFlowDiagnostics,
  FLOW_DIAGNOSTICS_EVENT,
  loadFlowDiagnostics,
  type DiagnosticEntry,
} from "../../utils/flow-diagnostics";

type Tab = "cabinet" | "register" | "engine";
type Selection =
  | { kind: "house" }
  | { kind: "collection"; id: string }
  | { kind: "folio"; id: string };
type RegisterFilter = "all" | "amendment" | "dossier" | "charter" | "collection";

interface HouseStore {
  loaded: boolean;
  tab: Tab;
  selection: Selection;
  house: HouseState;
  folios: Folio[];
  briefs: Record<string, ProjectBrief>;
  editions: Record<string, BriefEdition[]>;
  activeFolioId: string | null;
  profile: FlowProfile | null;
  log: DiagnosticEntry[];
  status: string;
  error: boolean;
  newArticle: string;
  newSeverity: "must" | "prefer";
  confirmDissolve: boolean;
  filter: RegisterFilter;
}

/* ── Module helpers (kept out of the component so handlers can use them) ── */

async function commit(state: HouseStore, work: Promise<HouseState>, done = "Filed.") {
  try {
    state.house = await work;
    state.status = done;
    state.error = false;
  } catch (error) {
    state.status =
      error instanceof Error ? error.message : "That could not be saved on this device.";
    state.error = true;
  }
}

/** Typewriter date stamp: 29 SEPT 2026 · 14:05. */
function stamp(ts: number): string {
  const d = new Date(ts);
  const day = d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
  const time = d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  return `${day} · ${time}`.toUpperCase();
}

function seconds(ms: number): string {
  return ms >= 60_000 ? `${Math.round(ms / 6_000) / 10} min` : `${Math.round(ms / 1000)} s`;
}

function hourLabel(hour: number): string {
  return new Date(2000, 0, 1, hour).toLocaleTimeString(undefined, { hour: "numeric" });
}

function ownerName(state: HouseStore, ownerRef: string): string {
  if (ownerRef === "house") return state.house.house.name || "The House";
  const collection = state.house.collections.find((c) => c.id === ownerRef);
  if (collection) return collection.name;
  return state.folios.find((f) => f.id === ownerRef)?.name ?? "A folio";
}

function matchesFilter(entry: LedgerEntry, filter: RegisterFilter): boolean {
  switch (filter) {
    case "amendment":
      return entry.source === "amendment";
    case "dossier":
      return entry.layer !== "charter" && !!entry.field && entry.source !== "amendment";
    case "charter":
      return entry.layer === "charter";
    case "collection":
      return entry.layer === "collection";
    default:
      return true;
  }
}

function fieldLabel(field?: string): string {
  if (!field) return "";
  if (field === "must" || field === "prefer") return field === "must" ? "Article (must)" : "Article (prefer)";
  return DOSSIER_FIELD_LABELS[field as DossierField] ?? field;
}

const LEGEND: Array<[string, string]> = [
  ["The House", "You. Defaults every piece inherits, and the house charter."],
  ["Collection", "A series — a column, a book's chapters, a newsletter. Narrows the House for its folios."],
  ["Folio", "One piece. Its dossier has the last word on what it is for."],
  ["Charter", "Standards that follow you. Every article from above still applies below."],
  ["Edition · Revision", "An edition changes what the words are for; a revision changes the words."],
  ["Amendment", "A dossier change the draft itself proposed, and you filed."],
];

export default component$(() => {
  const location = useLocation();
  const state = useStore<HouseStore>({
    loaded: false,
    tab: "cabinet",
    selection: { kind: "house" },
    house: emptyHouseState(),
    folios: [],
    briefs: {},
    editions: {},
    activeFolioId: null,
    profile: null,
    log: [],
    status: "",
    error: false,
    newArticle: "",
    newSeverity: "prefer",
    confirmDissolve: false,
    filter: "all",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const params = location.url.searchParams;
    const [house, folios, briefs, active, profile, log] = await Promise.all([
      loadHouseState(),
      loadFoliosFromIdb(),
      loadAllBriefsFromIdb(),
      loadActiveFolioIdFromIdb(),
      loadMetaFromIdb<FlowProfile>("flow-profile"),
      loadFlowDiagnostics(),
    ]);
    state.house = house;
    state.folios = [...folios].sort((a, b) => b.updatedAt - a.updatedAt);
    state.briefs = Object.fromEntries(briefs.map((b) => [b.folioId, b.brief]));
    state.activeFolioId = active;
    state.profile = normalizeProfile(profile);
    state.log = [...log].reverse();
    const editions = await Promise.all(folios.map((f) => loadBriefEditions(f.id)));
    state.editions = Object.fromEntries(folios.map((f, i) => [f.id, editions[i]]));

    const requested = params.get("folio");
    const tab = params.get("tab");
    if (tab === "register" || tab === "engine") state.tab = tab;
    if (requested && folios.some((f) => f.id === requested))
      state.selection = { kind: "folio", id: requested };
    else if (active && folios.some((f) => f.id === active))
      state.selection = { kind: "folio", id: active };
    state.loaded = true;

    const onHouse = (event: Event) => {
      state.house = (event as CustomEvent<HouseChangedDetail>).detail.state;
    };
    const onLog = (event: Event) => {
      state.log = [(event as CustomEvent<DiagnosticEntry>).detail, ...state.log].slice(0, 300);
    };
    window.addEventListener(HOUSE_CHANGED_EVENT, onHouse);
    window.addEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    cleanup(() => {
      window.removeEventListener(HOUSE_CHANGED_EVENT, onHouse);
      window.removeEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    });
  });

  const select = $((selection: Selection) => {
    state.selection = selection;
    state.newArticle = "";
    state.newSeverity = "prefer";
    state.confirmDissolve = false;
    state.status = "";
  });

  const addArticle = $(async (scope: CharterScope, ownerRef: string) => {
    const text = state.newArticle.trim();
    if (!text) return;
    await commit(
      state,
      upsertCharterItem({ scope, ownerRef, text, severity: state.newSeverity, kind: "other" }),
      "Article added to the charter.",
    );
    if (!state.error) state.newArticle = "";
  });

  const founding = $(async () => {
    const before = new Set(state.house.collections.map((c) => c.id));
    await commit(state, createCollection("New collection"), "Collection founded.");
    const fresh = state.house.collections.find((c) => !before.has(c.id));
    if (fresh) await select({ kind: "collection", id: fresh.id });
  });

  const exportEngine = $(() => {
    const blob = new Blob(
      [
        JSON.stringify(
          { exportedAt: new Date().toISOString(), profile: state.profile, log: state.log, house: state.house },
          null,
          2,
        ),
      ],
      { type: "application/json" },
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `twyne-engine-room-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });

  /* ── Pieces of the page ─────────────────────────────────────── */

  const houseName = state.house.house.name;
  const collections = state.house.collections;
  const looseFolios = state.folios.filter((f) => !collectionForFolio(state.house, f.id));
  const sel = state.selection;

  const layerStamp = (layer: ContextLayer | "charter" | null) =>
    layer ? (
      <span class={`house-stamp house-stamp--${layer}`}>
        {layer === "charter" ? "Charter" : LAYER_LABELS[layer]}
      </span>
    ) : null;

  const folder = (folio: Folio) => {
    const brief = state.briefs[folio.id];
    const editions = state.editions[folio.id]?.length ?? 0;
    const articles = state.house.charter.filter((c) => c.ownerRef === folio.id).length;
    return (
      <button
        key={folio.id}
        type="button"
        class="house-folder"
        aria-current={sel.kind === "folio" && sel.id === folio.id ? "true" : undefined}
        onClick$={() => select({ kind: "folio", id: folio.id })}
      >
        <span class="house-folder__name">{folio.name || "Untitled"}</span>
        <span class="house-folder__marks">
          {brief ? <span title="Dossier filed">D</span> : <span title="No dossier">—</span>}
          {editions > 0 && <span title={`${editions} earlier editions`}>{editions}ed</span>}
          {articles > 0 && <span title="Charter articles">§{articles}</span>}
          {state.activeFolioId === folio.id && <span title="Open on the desk">●</span>}
        </span>
      </button>
    );
  };

  const article = (item: CharterItem, inherited: boolean) => (
    <li key={item.id} class={["house-article", { "house-article--inherited": inherited }]}>
      {inherited ? (
        <span class="house-article__text">{item.text}</span>
      ) : (
        <input
          class="house-input house-article__text"
          value={item.text}
          aria-label="Charter article"
          onChange$={(_, el) => {
            const text = el.value.trim();
            if (!text || text === item.text) return;
            void commit(state, upsertCharterItem({ ...item, text }), "Article amended.");
          }}
        />
      )}
      <span class="house-article__controls">
        {inherited ? (
          layerStamp(item.scope === "house" ? "house" : "collection")
        ) : null}
        <button
          type="button"
          class="house-severity"
          data-severity={item.severity}
          disabled={inherited}
          title={
            inherited
              ? "Set where this article was written"
              : item.severity === "must"
                ? "A requirement. Click to make it a preference."
                : "A preference. Click to make it a requirement."
          }
          onClick$={() =>
            commit(
              state,
              upsertCharterItem({ ...item, severity: item.severity === "must" ? "prefer" : "must" }),
              "Article amended.",
            )
          }
        >
          {item.severity}
        </button>
        {!inherited && (
          <button
            type="button"
            class="house-remove"
            aria-label={`Withdraw: ${item.text}`}
            title="Withdraw this article"
            onClick$={() => commit(state, removeCharterItem(item.id), "Article withdrawn.")}
          >
            ✕
          </button>
        )}
      </span>
    </li>
  );

  const charterSection = (scope: CharterScope, ownerRef: string, inherited: CharterItem[]) => {
    const own = state.house.charter
      .filter((c) => c.ownerRef === ownerRef)
      .sort((a, b) => a.order - b.order);
    return (
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Charter</h3>
          <span class="house-section__note">
            {scope === "house"
              ? "Standards for everything you write"
              : scope === "collection"
                ? "Standards for every piece in this collection"
                : "Standards for this piece alone"}
          </span>
        </header>
        {inherited.length + own.length === 0 ? (
          <p class="house-folder__empty">
            No articles yet. Twyne checks your draft against each one on a pause, and says so in
            the margin when a passage breaks it.
          </p>
        ) : (
          <ol class="house-charter">
            {inherited.map((item) => article(item, true))}
            {own.map((item) => article(item, false))}
          </ol>
        )}
        <form
          class="house-new-article"
          preventdefault:submit
          onSubmit$={() => addArticle(scope, ownerRef)}
        >
          <input
            value={state.newArticle}
            placeholder={
              scope === "house"
                ? "e.g. Cite a primary source for every statistic"
                : scope === "collection"
                  ? "e.g. Every issue opens on a scene, not a thesis"
                  : "e.g. Stay under 1,200 words"
            }
            aria-label="New charter article"
            onInput$={(_, el) => {
              state.newArticle = el.value;
            }}
          />
          <button
            type="button"
            class="house-severity"
            data-severity={state.newSeverity}
            onClick$={() => {
              state.newSeverity = state.newSeverity === "must" ? "prefer" : "must";
            }}
            title="Requirement or preference"
          >
            {state.newSeverity}
          </button>
          <button type="submit" class="btn-press" disabled={!state.newArticle.trim()}>
            Add article
          </button>
        </form>
      </section>
    );
  };

  const saveLine = state.status ? (
    <span class={["house-saved", { "house-saved--error": state.error }]} role="status">
      {state.status}
    </span>
  ) : (
    <span class="house-saved">Changes are filed as you make them.</span>
  );

  /* ── Sheets ─────────────────────────────────────────────────── */

  const houseSheet = () => (
    <article class="house-sheet" key="house">
      <p class="house-sheet__kicker">The House</p>
      <h2 class="house-sheet__title">House defaults</h2>
      <p class="house-sheet__lede">
        Set these once. Every piece inherits them unless its collection, or its own dossier, says
        otherwise.
      </p>
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Dossier</h3>
          <span class="house-section__note">Inherited by every folio</span>
        </header>
        <div class="house-fields">
          {INHERITABLE_FIELDS.map((field) => (
            <label key={field} class="house-field">
              <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
              <span class="house-field__value">
                <textarea
                  class="house-input"
                  rows={1}
                  value={state.house.house.dossier[field] ?? ""}
                  placeholder="Leave blank to let each piece decide"
                  onChange$={(_, el) =>
                    commit(state, setHouseField(field, el.value), `${DOSSIER_FIELD_LABELS[field]} set for the House.`)
                  }
                />
              </span>
            </label>
          ))}
        </div>
      </section>
      {charterSection("house", "house", [])}
      <footer class="house-sheet__foot">{saveLine}</footer>
    </article>
  );

  const collectionSheet = (id: string) => {
    const collection = collections.find((c) => c.id === id);
    if (!collection) return houseSheet();
    const inherited = state.house.charter.filter((c) => c.ownerRef === "house");
    return (
      <article class="house-sheet" key={`collection-${id}`}>
        <p class="house-sheet__kicker">Collection</p>
        <input
          class="house-sheet__title"
          value={collection.name}
          aria-label="Collection name"
          onChange$={(_, el) => commit(state, updateCollection(id, { name: el.value }), "Renamed.")}
        />
        <textarea
          class="house-input house-sheet__lede"
          rows={1}
          value={collection.description}
          placeholder="What binds this series together?"
          aria-label="What binds this series together"
          onChange$={(_, el) => commit(state, updateCollection(id, { description: el.value }))}
        />

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier</h3>
            <span class="house-section__note">Narrows the House for these folios</span>
          </header>
          <div class="house-fields">
            {INHERITABLE_FIELDS.map((field) => {
              const fromHouse = state.house.house.dossier[field]?.trim();
              return (
                <label key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    <textarea
                      class="house-input"
                      rows={1}
                      value={collection.dossier[field] ?? ""}
                      placeholder={fromHouse ? `Inherits: ${fromHouse}` : "Leave blank to let each piece decide"}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          updateCollection(id, { field: { name: field, value: el.value } }),
                          `${DOSSIER_FIELD_LABELS[field]} set for ${collection.name}.`,
                        )
                      }
                    />
                    {fromHouse && collection.dossier[field]?.trim() && (
                      <span class="house-inherit">
                        {layerStamp("house")} overrides <s>{fromHouse}</s>
                      </span>
                    )}
                  </span>
                </label>
              );
            })}
          </div>
        </section>

        {charterSection("collection", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Folios in this collection</h3>
            <span class="house-section__note">A folio sits in one drawer at a time</span>
          </header>
          {state.folios.length === 0 ? (
            <p class="house-folder__empty">No folios yet.</p>
          ) : (
            <div class="house-members">
              {state.folios.map((folio) => {
                const other = collectionForFolio(state.house, folio.id);
                const inHere = other?.id === id;
                return (
                  <label key={folio.id} class="house-member">
                    <input
                      type="checkbox"
                      checked={inHere}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          setFolioCollection(folio.id, el.checked ? id : null),
                          el.checked ? `Filed under ${collection.name}.` : "Taken out of the collection.",
                        )
                      }
                    />
                    <span>
                      {folio.name || "Untitled"}
                      {other && !inHere && <small>now in {other.name}</small>}
                    </span>
                  </label>
                );
              })}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.confirmDissolve ? (
            <span style={{ display: "flex", gap: "0.5rem" }}>
              <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = false)}>
                Keep it
              </button>
              <button
                type="button"
                class="btn-press"
                onClick$={async () => {
                  await commit(state, deleteCollection(id), "Collection dissolved; its folios are loose.");
                  await select({ kind: "house" });
                }}
              >
                Dissolve
              </button>
            </span>
          ) : (
            <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = true)}>
              Dissolve collection…
            </button>
          )}
        </footer>
      </article>
    );
  };

  const folioSheet = (id: string) => {
    const folio = state.folios.find((f) => f.id === id);
    if (!folio) return houseSheet();
    const brief = state.briefs[id] ?? null;
    const stack = assembleContextStack(state.house, id, brief);
    const models = contextForModels(stack);
    const inherited = stack.charter.filter((c) => c.inherited);
    const editions = state.editions[id] ?? [];
    return (
      <article class="house-sheet" key={`folio-${id}`}>
        <p class="house-sheet__kicker">
          Folio{stack.collection ? ` · ${stack.collection.name}` : ""}
        </p>
        <h2 class="house-sheet__title">{folio.name || "Untitled"}</h2>
        <p class="house-sheet__lede">
          What this piece is for, and where each part of that came from.
        </p>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier, as the models see it</h3>
            <Link href={`/dossier/refine/?folio=${encodeURIComponent(id)}`} class="flow-link">
              Refine the dossier →
            </Link>
          </header>
          <div class="house-fields">
            {DOSSIER_FIELDS.map((field) => {
              const entry = stack.fields[field];
              return (
                <div key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    {entry.value ? (
                      <span class="house-input" style={{ whiteSpace: "pre-wrap" }}>
                        {entry.value}
                      </span>
                    ) : (
                      <span class="house-folder__empty">Nothing set at any level.</span>
                    )}
                    {(entry.layer || entry.shadowed.length > 0) && (
                      <span class="house-inherit">
                        {layerStamp(entry.layer)}
                        {entry.shadowed.map((s) => (
                          <span key={s.layer}>
                            overrides {LAYER_LABELS[s.layer].toLowerCase()} <s>{s.value}</s>
                          </span>
                        ))}
                      </span>
                    )}
                  </span>
                </div>
              );
            })}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Filed under</h3>
          </header>
          <select
            class="btn-paper"
            value={stack.collection?.id ?? ""}
            aria-label="Collection"
            onChange$={(_, el) =>
              commit(
                state,
                setFolioCollection(id, el.value || null),
                el.value ? "Filed under the collection." : "Now a loose folio.",
              )
            }
          >
            <option value="">Loose — no collection</option>
            {collections.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </section>

        {charterSection("folio", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">What the models read</h3>
            <span class="house-section__note">Exactly this, ahead of every judgement</span>
          </header>
          {models.text ? (
            <pre class="house-carbon">{models.text}</pre>
          ) : (
            <p class="house-folder__empty">Nothing yet — the models see only the draft.</p>
          )}
          <div class="house-costs">
            {models.layers.map((l) => (
              <span key={l.layer} class="house-chip">
                {l.layer === "charter" ? "Charter" : LAYER_LABELS[l.layer]} · ≈{l.tokens} tokens
              </span>
            ))}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Editions</h3>
            <span class="house-section__note">
              {editions.length
                ? `${editions.length} earlier ${editions.length === 1 ? "edition" : "editions"} of this dossier`
                : "The dossier has not changed since it was filed"}
            </span>
          </header>
          {editions.length > 0 && (
            <div class="house-register" style={{ marginTop: 0 }}>
              {editions.slice(0, 5).map((edition) => (
                <div
                  key={edition.id}
                  class={[
                    "house-register__row",
                    { "house-register__row--amendment": edition.source === "amendment" },
                  ]}
                >
                  <span class="house-register__when">{stamp(edition.savedAt)}</span>
                  <span class="house-register__what">
                    {edition.source ? LEDGER_SOURCE_LABELS[edition.source] : "Superseded"}
                  </span>
                  <span class="house-register__diff">
                    <span>{edition.brief.answers.goal || edition.brief.answers.workingTitle}</span>
                    {edition.reason && <span class="house-register__why">{edition.reason}</span>}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.activeFolioId === id ? (
            <Link href="/editor/" class="btn-press">
              Back to the desk
            </Link>
          ) : null}
        </footer>
      </article>
    );
  };

  /* ── Tabs ───────────────────────────────────────────────────── */

  const cabinet = (
    <div class="house-cabinet">
      <nav class="house-diagram" aria-label="The House, its collections and folios">
        <p class="house-diagram__caption">The cabinet</p>
        <div class="house-tree">
          <button
            type="button"
            class="house-node house-node--house"
            aria-current={sel.kind === "house" ? "true" : undefined}
            onClick$={() => select({ kind: "house" })}
          >
            <span class="house-node__kind">The House</span>
            <span class="house-node__name">{houseName || "Your house"}</span>
            <span class="house-node__meta">
              <span class="house-chip">
                {Object.values(state.house.house.dossier).filter((v) => v?.trim()).length} defaults
              </span>
              <span class="house-chip">
                §{state.house.charter.filter((c) => c.ownerRef === "house").length} house charter
              </span>
            </span>
          </button>

          {collections.map((collection) => (
            <div key={collection.id} class="house-drawer">
              <button
                type="button"
                class="house-node house-node--collection"
                aria-current={sel.kind === "collection" && sel.id === collection.id ? "true" : undefined}
                onClick$={() => select({ kind: "collection", id: collection.id })}
              >
                <span class="house-node__kind">Collection</span>
                <span class="house-node__name">{collection.name}</span>
                <span class="house-node__meta">
                  <span class="house-chip">
                    {collection.folioIds.length} {collection.folioIds.length === 1 ? "folio" : "folios"}
                  </span>
                  {state.house.charter.some((c) => c.ownerRef === collection.id) && (
                    <span class="house-chip">
                      §{state.house.charter.filter((c) => c.ownerRef === collection.id).length}
                    </span>
                  )}
                </span>
              </button>
              <div class="house-folders">
                {collection.folioIds
                  .map((fid) => state.folios.find((f) => f.id === fid))
                  .filter((f): f is Folio => !!f)
                  .map(folder)}
                {collection.folioIds.length === 0 && (
                  <p class="house-folder__empty">Empty drawer — file folios from its sheet.</p>
                )}
              </div>
            </div>
          ))}

          <div class="house-drawer">
            <div class="house-node house-node--collection house-node--loose" aria-hidden="true">
              <span class="house-node__kind">Loose folios</span>
              <span class="house-node__name">Not in a collection</span>
            </div>
            <div class="house-folders">
              {looseFolios.map(folder)}
              {looseFolios.length === 0 && state.loaded && (
                <p class="house-folder__empty">Every folio is filed.</p>
              )}
            </div>
          </div>

          <button type="button" class="btn-paper" onClick$={founding}>
            + Found a collection
          </button>
        </div>

        <dl class="house-legend">
          {LEGEND.map(([term, meaning]) => (
            <div key={term}>
              <dt>{term}</dt>
              <dd>{meaning}</dd>
            </div>
          ))}
        </dl>
      </nav>

      {sel.kind === "house"
        ? houseSheet()
        : sel.kind === "collection"
          ? collectionSheet(sel.id)
          : folioSheet(sel.id)}
    </div>
  );

  const entries = state.house.ledger.filter((e) => matchesFilter(e, state.filter));
  const register = (
    <div>
      <div class="house-register__filters" role="group" aria-label="Filter the register">
        {(
          [
            ["all", "Everything"],
            ["amendment", "Amendments"],
            ["dossier", "Dossiers"],
            ["charter", "Charters"],
            ["collection", "Collections"],
          ] as const
        ).map(([value, label]) => (
          <button
            key={value}
            type="button"
            class="house-filter"
            aria-pressed={state.filter === value}
            onClick$={() => (state.filter = value)}
          >
            {label}
          </button>
        ))}
      </div>
      {entries.length === 0 ? (
        <p class="house-empty">
          The register is empty. It fills as dossiers are filed, refined and amended, and as
          charters change.
        </p>
      ) : (
        <div class="house-register">
          {entries.slice(0, 200).map((entry) => (
            <div
              key={entry.id}
              class={[
                "house-register__row",
                { "house-register__row--amendment": entry.source === "amendment" },
              ]}
            >
              <span class="house-register__when">{stamp(entry.at)}</span>
              <span class="house-register__what">
                <strong>{ownerName(state, entry.ownerRef)}</strong>
                <span>
                  {layerStamp(entry.layer === "charter" ? "charter" : entry.source === "amendment" ? "amendment" : entry.layer)}
                </span>
              </span>
              <span class="house-register__diff">
                <span class="house-section__note" style={{ fontStyle: "normal" }}>
                  {LEDGER_SOURCE_LABELS[entry.source]}
                  {entry.field ? ` — ${fieldLabel(entry.field)}` : ""}
                </span>
                {entry.from && <span class="house-register__from">{entry.from}</span>}
                {entry.to && <span>{entry.to}</span>}
                {entry.reason && <span class="house-register__why">{entry.reason}</span>}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const profile = state.profile;
  const t = profile ? thresholdsFor(profile) : null;
  const kinds = Object.keys(KIND_LABELS) as FlowItemKind[];
  const engine = (
    <div class="house-engine">
      <p class="house-sheet__lede" style={{ margin: 0 }}>
        What the flow reader has learned about how you write, the thresholds it derived from
        that, and every decision it made — for tuning the plumbing. Only rhythms and reactions are
        recorded here, never your words.
      </p>
      {profile && t && (
        <div class="house-gauges">
          {[
            ["Pauses learned", String(profile.pauses.length), profile.pauses.length >= 12 ? "Thresholds fitted to you" : "Defaults until 12"],
            ["Stuck after", seconds(t.stuckPauseMs), "a pause after circling"],
            ["Focus after", seconds(t.flowMs), "of steady writing"],
            ["Focus ends after", seconds(t.exitPauseMs), "a pause this long"],
            ["Times in flow", String(profile.flowEntries.length), "confirmed runs"],
            ["Hand overrides", String(profile.overrides), "you left focus yourself"],
            [
              "Usual hours",
              writingHours(profile).map(hourLabel).join(", ") || "—",
              "when you write most",
            ],
          ].map(([label, value, hint]) => (
            <div key={label} class="house-gauge">
              <div class="house-gauge__label">{label}</div>
              <div class="house-gauge__value">{value}</div>
              <div class="house-gauge__hint">{hint}</div>
            </div>
          ))}
        </div>
      )}

      {profile && (
        <section class="house-sheet" style={{ animation: "none" }}>
          <header class="house-section__head">
            <h3 class="house-section__title">What helps you</h3>
            <span class="house-section__note">Weight 1.0 is neutral; used kinds rise, waved-away kinds sink</span>
          </header>
          <div class="house-weights">
            {kinds.map((kind) => {
              const w = kindWeight(profile, kind);
              const s = profile.kinds[kind];
              return (
                <div key={kind} class="house-weight" title={s ? `${s.shown} shown · ${s.engaged} used · ${s.dismissed} set aside` : "Not seen yet"}>
                  <span>{KIND_LABELS[kind]}</span>
                  <span class="house-weight__bar">
                    <span style={{ width: `${(w / 1.8) * 100}%` }} />
                  </span>
                  <span>{w.toFixed(2)}</span>
                </div>
              );
            })}
          </div>
        </section>
      )}

      <section>
        <header class="house-section__head">
          <h3 class="house-section__title">Decision log</h3>
          <span style={{ display: "flex", gap: "0.5rem" }}>
            <button type="button" class="btn-paper" onClick$={exportEngine}>
              Export JSON
            </button>
            <button
              type="button"
              class="btn-paper"
              onClick$={async () => {
                await clearFlowDiagnostics();
                state.log = [];
              }}
            >
              Clear
            </button>
          </span>
        </header>
        {state.log.length === 0 ? (
          <p class="house-empty">
            Nothing logged yet. Write for a while on the desk and the reader's decisions appear
            here as they happen.
          </p>
        ) : (
          <div class="house-log">
            {state.log.map((entry) => (
              <details key={entry.id} class="house-log__row">
                <summary style={{ display: "contents" }}>
                  <span class="house-register__when">
                    {new Date(entry.at).toLocaleTimeString()}
                  </span>
                  <span class={`house-log__kind house-log__kind--${entry.kind}`}>{entry.kind}</span>
                  <span>{entry.summary}</span>
                </summary>
                {entry.detail && (
                  <pre style={{ gridColumn: "1 / -1" }}>{JSON.stringify(entry.detail, null, 2)}</pre>
                )}
              </details>
            ))}
          </div>
        )}
      </section>
    </div>
  );

  return (
    <div class="house">
      <div class="house__inner">
        <header class="house-letterhead">
          <div>
            <p class="house-letterhead__eyebrow">Maison d'édition</p>
            <input
              class="house-letterhead__name"
              value={houseName}
              placeholder="Name your house"
              aria-label="The name of your house"
              onChange$={(_, el) => commit(state, setHouseName(el.value), "The letterhead is reset.")}
            />
            <p class="house-letterhead__motto">
              Everything that tells Twyne what your writing is for — and how it has changed.
            </p>
          </div>
          <div class="house-letterhead__actions">
            <Link href="/library/" class="btn-paper">
              Library
            </Link>
            <Link href="/editor/" class="btn-press">
              ← The desk
            </Link>
          </div>
        </header>

        <div class="house-tabs" role="tablist" aria-label="The House">
          {(
            [
              ["cabinet", "The cabinet", null],
              ["register", "The register", state.house.ledger.length || null],
              ["engine", "Engine room", null],
            ] as const
          ).map(([tab, label, count]) => (
            <button
              key={tab}
              type="button"
              role="tab"
              class="house-tab"
              aria-selected={state.tab === tab}
              onClick$={() => (state.tab = tab)}
            >
              {label}
              {count ? <span class="house-tab__count">{count}</span> : null}
            </button>
          ))}
        </div>

        {!state.loaded ? (
          <p class="house-empty">Opening the cabinet…</p>
        ) : state.tab === "cabinet" ? (
          cabinet
        ) : state.tab === "register" ? (
          register
        ) : (
          engine
        )}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "The House · Twyne",
  meta: [
    {
      name: "description",
      content: "Your house, its collections, dossiers and charters — everything that tells Twyne what your writing is for.",
    },
  ],
};

toolUseResult.content:
/**
 * The House — where a writer sees, and shapes, everything that tells Twyne
 * what their writing is for.
 *
 *   Cabinet      the hierarchy, drawn as a filing cabinet: the House on its
 *                letterhead, collections as drawers, folios as folders. Pick
 *                any of them to open its sheet — its dossier, its charter,
 *                and exactly what the models are handed.
 *   Register     every change to that context, newest first: who or what
 *                made it, from what, to what, and why.
 *   Engine room  for whoever is tuning the plumbing: what the flow reader has
 *                learned, the thresholds it derived, and its decision log.
 */
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link, useLocation, type DocumentHead } from "@qwik.dev/router";
import "../../components/house/house.css";
import type { Folio, ProjectBrief } from "../../types";
import {
  loadActiveFolioIdFromIdb,
  loadAllBriefsFromIdb,
  loadFoliosFromIdb,
  loadMetaFromIdb,
} from "../../utils/idb";
import { loadBriefEditions, type BriefEdition } from "../../utils/brief-history";
import {
  assembleContextStack,
  collectionForFolio,
  contextForModels,
  DOSSIER_FIELD_LABELS,
  DOSSIER_FIELDS,
  emptyHouseState,
  INHERITABLE_FIELDS,
  LAYER_LABELS,
  LEDGER_SOURCE_LABELS,
  type CharterItem,
  type CharterScope,
  type ContextLayer,
  type DossierField,
  type HouseState,
  type LedgerEntry,
} from "../../utils/house-model";
import {
  createCollection,
  deleteCollection,
  HOUSE_CHANGED_EVENT,
  loadHouseState,
  removeCharterItem,
  setFolioCollection,
  setHouseField,
  setHouseName,
  updateCollection,
  upsertCharterItem,
  type HouseChangedDetail,
} from "../../utils/house-store";
import {
  kindWeight,
  normalizeProfile,
  thresholdsFor,
  writingHours,
  type FlowProfile,
} from "../../utils/flow-profile";
import { KIND_LABELS, type FlowItemKind } from "../../utils/flow-items";
import {
  clearFlowDiagnostics,
  FLOW_DIAGNOSTICS_EVENT,
  loadFlowDiagnostics,
  type DiagnosticEntry,
} from "../../utils/flow-diagnostics";

type Tab = "cabinet" | "register" | "engine";
type Selection =
  | { kind: "house" }
  | { kind: "collection"; id: string }
  | { kind: "folio"; id: string };
type RegisterFilter = "all" | "amendment" | "dossier" | "charter" | "collection";

interface HouseStore {
  loaded: boolean;
  tab: Tab;
  selection: Selection;
  house: HouseState;
  folios: Folio[];
  briefs: Record<string, ProjectBrief>;
  editions: Record<string, BriefEdition[]>;
  activeFolioId: string | null;
  profile: FlowProfile | null;
  log: DiagnosticEntry[];
  status: string;
  error: boolean;
  newArticle: string;
  newSeverity: "must" | "prefer";
  confirmDissolve: boolean;
  filter: RegisterFilter;
}

/* ── Module helpers (kept out of the component so handlers can use them) ── */

async function commit(state: HouseStore, work: Promise<HouseState>, done = "Filed.") {
  try {
    state.house = await work;
    state.status = done;
    state.error = false;
  } catch (error) {
    state.status =
      error instanceof Error ? error.message : "That could not be saved on this device.";
    state.error = true;
  }
}

/** Typewriter date stamp: 29 SEPT 2026 · 14:05. */
function stamp(ts: number): string {
  const d = new Date(ts);
  const day = d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
  const time = d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  return `${day} · ${time}`.toUpperCase();
}

function seconds(ms: number): string {
  return ms >= 60_000 ? `${Math.round(ms / 6_000) / 10} min` : `${Math.round(ms / 1000)} s`;
}

function hourLabel(hour: number): string {
  return new Date(2000, 0, 1, hour).toLocaleTimeString(undefined, { hour: "numeric" });
}

function ownerName(state: HouseStore, ownerRef: string): string {
  if (ownerRef === "house") return state.house.house.name || "The House";
  const collection = state.house.collections.find((c) => c.id === ownerRef);
  if (collection) return collection.name;
  return state.folios.find((f) => f.id === ownerRef)?.name ?? "A folio";
}

function matchesFilter(entry: LedgerEntry, filter: RegisterFilter): boolean {
  switch (filter) {
    case "amendment":
      return entry.source === "amendment";
    case "dossier":
      return entry.layer !== "charter" && !!entry.field && entry.source !== "amendment";
    case "charter":
      return entry.layer === "charter";
    case "collection":
      return entry.layer === "collection";
    default:
      return true;
  }
}

function fieldLabel(field?: string): string {
  if (!field) return "";
  if (field === "must" || field === "prefer") return field === "must" ? "Article (must)" : "Article (prefer)";
  return DOSSIER_FIELD_LABELS[field as DossierField] ?? field;
}

const LEGEND: Array<[string, string]> = [
  ["The House", "You. Defaults every piece inherits, and the house charter."],
  ["Collection", "A series — a column, a book's chapters, a newsletter. Narrows the House for its folios."],
  ["Folio", "One piece. Its dossier has the last word on what it is for."],
  ["Charter", "Standards that follow you. Every article from above still applies below."],
  ["Edition · Revision", "An edition changes what the words are for; a revision changes the words."],
  ["Amendment", "A dossier change the draft itself proposed, and you filed."],
];

export default component$(() => {
  const location = useLocation();
  const state = useStore<HouseStore>({
    loaded: false,
    tab: "cabinet",
    selection: { kind: "house" },
    house: emptyHouseState(),
    folios: [],
    briefs: {},
    editions: {},
    activeFolioId: null,
    profile: null,
    log: [],
    status: "",
    error: false,
    newArticle: "",
    newSeverity: "prefer",
    confirmDissolve: false,
    filter: "all",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const params = location.url.searchParams;
    const [house, folios, briefs, active, profile, log] = await Promise.all([
      loadHouseState(),
      loadFoliosFromIdb(),
      loadAllBriefsFromIdb(),
      loadActiveFolioIdFromIdb(),
      loadMetaFromIdb<FlowProfile>("flow-profile"),
      loadFlowDiagnostics(),
    ]);
    state.house = house;
    state.folios = [...folios].sort((a, b) => b.updatedAt - a.updatedAt);
    state.briefs = Object.fromEntries(briefs.map((b) => [b.folioId, b.brief]));
    state.activeFolioId = active;
    state.profile = normalizeProfile(profile);
    state.log = [...log].reverse();
    const editions = await Promise.all(folios.map((f) => loadBriefEditions(f.id)));
    state.editions = Object.fromEntries(folios.map((f, i) => [f.id, editions[i]]));

    const requested = params.get("folio");
    const tab = params.get("tab");
    if (tab === "register" || tab === "engine") state.tab = tab;
    if (requested && folios.some((f) => f.id === requested))
      state.selection = { kind: "folio", id: requested };
    else if (active && folios.some((f) => f.id === active))
      state.selection = { kind: "folio", id: active };
    state.loaded = true;

    const onHouse = (event: Event) => {
      state.house = (event as CustomEvent<HouseChangedDetail>).detail.state;
    };
    const onLog = (event: Event) => {
      state.log = [(event as CustomEvent<DiagnosticEntry>).detail, ...state.log].slice(0, 300);
    };
    window.addEventListener(HOUSE_CHANGED_EVENT, onHouse);
    window.addEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    cleanup(() => {
      window.removeEventListener(HOUSE_CHANGED_EVENT, onHouse);
      window.removeEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
    });
  });

  const select = $((selection: Selection) => {
    state.selection = selection;
    state.newArticle = "";
    state.newSeverity = "prefer";
    state.confirmDissolve = false;
    state.status = "";
  });

  const addArticle = $(async (scope: CharterScope, ownerRef: string) => {
    const text = state.newArticle.trim();
    if (!text) return;
    await commit(
      state,
      upsertCharterItem({ scope, ownerRef, text, severity: state.newSeverity, kind: "other" }),
      "Article added to the charter.",
    );
    if (!state.error) state.newArticle = "";
  });

  const founding = $(async () => {
    const before = new Set(state.house.collections.map((c) => c.id));
    await commit(state, createCollection("New collection"), "Collection founded.");
    const fresh = state.house.collections.find((c) => !before.has(c.id));
    if (fresh) await select({ kind: "collection", id: fresh.id });
  });

  const exportEngine = $(() => {
    const blob = new Blob(
      [
        JSON.stringify(
          { exportedAt: new Date().toISOString(), profile: state.profile, log: state.log, house: state.house },
          null,
          2,
        ),
      ],
      { type: "application/json" },
    );
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `twyne-engine-room-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });

  /* ── Pieces of the page ─────────────────────────────────────── */

  const houseName = state.house.house.name;
  const collections = state.house.collections;
  const looseFolios = state.folios.filter((f) => !collectionForFolio(state.house, f.id));
  const sel = state.selection;

  const layerStamp = (layer: ContextLayer | "charter" | null) =>
    layer ? (
      <span class={`house-stamp house-stamp--${layer}`}>
        {layer === "charter" ? "Charter" : LAYER_LABELS[layer]}
      </span>
    ) : null;

  const folder = (folio: Folio) => {
    const brief = state.briefs[folio.id];
    const editions = state.editions[folio.id]?.length ?? 0;
    const articles = state.house.charter.filter((c) => c.ownerRef === folio.id).length;
    return (
      <button
        key={folio.id}
        type="button"
        class="house-folder"
        aria-current={sel.kind === "folio" && sel.id === folio.id ? "true" : undefined}
        onClick$={() => select({ kind: "folio", id: folio.id })}
      >
        <span class="house-folder__name">{folio.name || "Untitled"}</span>
        <span class="house-folder__marks">
          {brief ? <span title="Dossier filed">D</span> : <span title="No dossier">—</span>}
          {editions > 0 && <span title={`${editions} earlier editions`}>{editions}ed</span>}
          {articles > 0 && <span title="Charter articles">§{articles}</span>}
          {state.activeFolioId === folio.id && <span title="Open on the desk">●</span>}
        </span>
      </button>
    );
  };

  const article = (item: CharterItem, inherited: boolean) => (
    <li key={item.id} class={["house-article", { "house-article--inherited": inherited }]}>
      {inherited ? (
        <span class="house-article__text">{item.text}</span>
      ) : (
        <input
          class="house-input house-article__text"
          value={item.text}
          aria-label="Charter article"
          onChange$={(_, el) => {
            const text = el.value.trim();
            if (!text || text === item.text) return;
            void commit(state, upsertCharterItem({ ...item, text }), "Article amended.");
          }}
        />
      )}
      <span class="house-article__controls">
        {inherited ? (
          layerStamp(item.scope === "house" ? "house" : "collection")
        ) : null}
        <button
          type="button"
          class="house-severity"
          data-severity={item.severity}
          disabled={inherited}
          title={
            inherited
              ? "Set where this article was written"
              : item.severity === "must"
                ? "A requirement. Click to make it a preference."
                : "A preference. Click to make it a requirement."
          }
          onClick$={() =>
            commit(
              state,
              upsertCharterItem({ ...item, severity: item.severity === "must" ? "prefer" : "must" }),
              "Article amended.",
            )
          }
        >
          {item.severity}
        </button>
        {!inherited && (
          <button
            type="button"
            class="house-remove"
            aria-label={`Withdraw: ${item.text}`}
            title="Withdraw this article"
            onClick$={() => commit(state, removeCharterItem(item.id), "Article withdrawn.")}
          >
            ✕
          </button>
        )}
      </span>
    </li>
  );

  const charterSection = (scope: CharterScope, ownerRef: string, inherited: CharterItem[]) => {
    const own = state.house.charter
      .filter((c) => c.ownerRef === ownerRef)
      .sort((a, b) => a.order - b.order);
    return (
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Charter</h3>
          <span class="house-section__note">
            {scope === "house"
              ? "Standards for everything you write"
              : scope === "collection"
                ? "Standards for every piece in this collection"
                : "Standards for this piece alone"}
          </span>
        </header>
        {inherited.length + own.length === 0 ? (
          <p class="house-folder__empty">
            No articles yet. Twyne checks your draft against each one on a pause, and says so in
            the margin when a passage breaks it.
          </p>
        ) : (
          <ol class="house-charter">
            {inherited.map((item) => article(item, true))}
            {own.map((item) => article(item, false))}
          </ol>
        )}
        <form
          class="house-new-article"
          preventdefault:submit
          onSubmit$={() => addArticle(scope, ownerRef)}
        >
          <input
            value={state.newArticle}
            placeholder={
              scope === "house"
                ? "e.g. Cite a primary source for every statistic"
                : scope === "collection"
                  ? "e.g. Every issue opens on a scene, not a thesis"
                  : "e.g. Stay under 1,200 words"
            }
            aria-label="New charter article"
            onInput$={(_, el) => {
              state.newArticle = el.value;
            }}
          />
          <button
            type="button"
            class="house-severity"
            data-severity={state.newSeverity}
            onClick$={() => {
              state.newSeverity = state.newSeverity === "must" ? "prefer" : "must";
            }}
            title="Requirement or preference"
          >
            {state.newSeverity}
          </button>
          <button type="submit" class="btn-press" disabled={!state.newArticle.trim()}>
            Add article
          </button>
        </form>
      </section>
    );
  };

  const saveLine = state.status ? (
    <span class={["house-saved", { "house-saved--error": state.error }]} role="status">
      {state.status}
    </span>
  ) : (
    <span class="house-saved">Changes are filed as you make them.</span>
  );

  /* ── Sheets ─────────────────────────────────────────────────── */

  const houseSheet = () => (
    <article class="house-sheet" key="house">
      <p class="house-sheet__kicker">The House</p>
      <h2 class="house-sheet__title">House defaults</h2>
      <p class="house-sheet__lede">
        Set these once. Every piece inherits them unless its collection, or its own dossier, says
        otherwise.
      </p>
      <section class="house-section">
        <header class="house-section__head">
          <h3 class="house-section__title">Dossier</h3>
          <span class="house-section__note">Inherited by every folio</span>
        </header>
        <div class="house-fields">
          {INHERITABLE_FIELDS.map((field) => (
            <label key={field} class="house-field">
              <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
              <span class="house-field__value">
                <textarea
                  class="house-input"
                  rows={1}
                  value={state.house.house.dossier[field] ?? ""}
                  placeholder="Leave blank to let each piece decide"
                  onChange$={(_, el) =>
                    commit(state, setHouseField(field, el.value), `${DOSSIER_FIELD_LABELS[field]} set for the House.`)
                  }
                />
              </span>
            </label>
          ))}
        </div>
      </section>
      {charterSection("house", "house", [])}
      <footer class="house-sheet__foot">{saveLine}</footer>
    </article>
  );

  const collectionSheet = (id: string) => {
    const collection = collections.find((c) => c.id === id);
    if (!collection) return houseSheet();
    const inherited = state.house.charter.filter((c) => c.ownerRef === "house");
    return (
      <article class="house-sheet" key={`collection-${id}`}>
        <p class="house-sheet__kicker">Collection</p>
        <input
          class="house-sheet__title"
          value={collection.name}
          aria-label="Collection name"
          onChange$={(_, el) => commit(state, updateCollection(id, { name: el.value }), "Renamed.")}
        />
        <textarea
          class="house-input house-sheet__lede"
          rows={1}
          value={collection.description}
          placeholder="What binds this series together?"
          aria-label="What binds this series together"
          onChange$={(_, el) => commit(state, updateCollection(id, { description: el.value }))}
        />

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier</h3>
            <span class="house-section__note">Narrows the House for these folios</span>
          </header>
          <div class="house-fields">
            {INHERITABLE_FIELDS.map((field) => {
              const fromHouse = state.house.house.dossier[field]?.trim();
              return (
                <label key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    <textarea
                      class="house-input"
                      rows={1}
                      value={collection.dossier[field] ?? ""}
                      placeholder={fromHouse ? `Inherits: ${fromHouse}` : "Leave blank to let each piece decide"}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          updateCollection(id, { field: { name: field, value: el.value } }),
                          `${DOSSIER_FIELD_LABELS[field]} set for ${collection.name}.`,
                        )
                      }
                    />
                    {fromHouse && collection.dossier[field]?.trim() && (
                      <span class="house-inherit">
                        {layerStamp("house")} overrides <s>{fromHouse}</s>
                      </span>
                    )}
                  </span>
                </label>
              );
            })}
          </div>
        </section>

        {charterSection("collection", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Folios in this collection</h3>
            <span class="house-section__note">A folio sits in one drawer at a time</span>
          </header>
          {state.folios.length === 0 ? (
            <p class="house-folder__empty">No folios yet.</p>
          ) : (
            <div class="house-members">
              {state.folios.map((folio) => {
                const other = collectionForFolio(state.house, folio.id);
                const inHere = other?.id === id;
                return (
                  <label key={folio.id} class="house-member">
                    <input
                      type="checkbox"
                      checked={inHere}
                      onChange$={(_, el) =>
                        commit(
                          state,
                          setFolioCollection(folio.id, el.checked ? id : null),
                          el.checked ? `Filed under ${collection.name}.` : "Taken out of the collection.",
                        )
                      }
                    />
                    <span>
                      {folio.name || "Untitled"}
                      {other && !inHere && <small>now in {other.name}</small>}
                    </span>
                  </label>
                );
              })}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.confirmDissolve ? (
            <span style={{ display: "flex", gap: "0.5rem" }}>
              <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = false)}>
                Keep it
              </button>
              <button
                type="button"
                class="btn-press"
                onClick$={async () => {
                  await commit(state, deleteCollection(id), "Collection dissolved; its folios are loose.");
                  await select({ kind: "house" });
                }}
              >
                Dissolve
              </button>
            </span>
          ) : (
            <button type="button" class="btn-paper" onClick$={() => (state.confirmDissolve = true)}>
              Dissolve collection…
            </button>
          )}
        </footer>
      </article>
    );
  };

  const folioSheet = (id: string) => {
    const folio = state.folios.find((f) => f.id === id);
    if (!folio) return houseSheet();
    const brief = state.briefs[id] ?? null;
    const stack = assembleContextStack(state.house, id, brief);
    const models = contextForModels(stack);
    const inherited = stack.charter.filter((c) => c.inherited);
    const editions = state.editions[id] ?? [];
    return (
      <article class="house-sheet" key={`folio-${id}`}>
        <p class="house-sheet__kicker">
          Folio{stack.collection ? ` · ${stack.collection.name}` : ""}
        </p>
        <h2 class="house-sheet__title">{folio.name || "Untitled"}</h2>
        <p class="house-sheet__lede">
          What this piece is for, and where each part of that came from.
        </p>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Dossier, as the models see it</h3>
            <Link href={`/dossier/refine/?folio=${encodeURIComponent(id)}`} class="flow-link">
              Refine the dossier →
            </Link>
          </header>
          <div class="house-fields">
            {DOSSIER_FIELDS.map((field) => {
              const entry = stack.fields[field];
              return (
                <div key={field} class="house-field">
                  <span class="house-field__label">{DOSSIER_FIELD_LABELS[field]}</span>
                  <span class="house-field__value">
                    {entry.value ? (
                      <span class="house-input" style={{ whiteSpace: "pre-wrap" }}>
                        {entry.value}
                      </span>
                    ) : (
                      <span class="house-folder__empty">Nothing set at any level.</span>
                    )}
                    {(entry.layer || entry.shadowed.length > 0) && (
                      <span class="house-inherit">
                        {layerStamp(entry.layer)}
                        {entry.shadowed.map((s) => (
                          <span key={s.layer}>
                            overrides {LAYER_LABELS[s.layer].toLowerCase()} <s>{s.value}</s>
                          </span>
                        ))}
                      </span>
                    )}
                  </span>
                </div>
              );
            })}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Filed under</h3>
          </header>
          <select
            class="btn-paper"
            value={stack.collection?.id ?? ""}
            aria-label="Collection"
            onChange$={(_, el) =>
              commit(
                state,
                setFolioCollection(id, el.value || null),
                el.value ? "Filed under the collection." : "Now a loose folio.",
              )
            }
          >
            <option value="">Loose — no collection</option>
            {collections.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </section>

        {charterSection("folio", id, inherited)}

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">What the models read</h3>
            <span class="house-section__note">Exactly this, ahead of every judgement</span>
          </header>
          {models.text ? (
            <pre class="house-carbon">{models.text}</pre>
          ) : (
            <p class="house-folder__empty">Nothing yet — the models see only the draft.</p>
          )}
          <div class="house-costs">
            {models.layers.map((l) => (
              <span key={l.layer} class="house-chip">
                {l.layer === "charter" ? "Charter" : LAYER_LABELS[l.layer]} · ≈{l.tokens} tokens
              </span>
            ))}
          </div>
        </section>

        <section class="house-section">
          <header class="house-section__head">
            <h3 class="house-section__title">Editions</h3>
            <span class="house-section__note">
              {editions.length
                ? `${editions.length} earlier ${editions.length === 1 ? "edition" : "editions"} of this dossier`
                : "The dossier has not changed since it was filed"}
            </span>
          </header>
          {editions.length > 0 && (
            <div class="house-register" style={{ marginTop: 0 }}>
              {editions.slice(0, 5).map((edition) => (
                <div
                  key={edition.id}
                  class={[
                    "house-register__row",
                    { "house-register__row--amendment": edition.source === "amendment" },
                  ]}
                >
                  <span class="house-register__when">{stamp(edition.savedAt)}</span>
                  <span class="house-register__what">
                    {edition.source ? LEDGER_SOURCE_LABELS[edition.source] : "Superseded"}
                  </span>
                  <span class="house-register__diff">
                    <span>{edition.brief.answers.goal || edition.brief.answers.workingTitle}</span>
                    {edition.reason && <span class="house-register__why">{edition.reason}</span>}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>

        <footer class="house-sheet__foot">
          {saveLine}
          {state.activeFolioId === id ? (
            <Link href="/editor/" class="btn-press">
              Back to the desk
            </Link>
          ) : null}
        </footer>
      </article>
    );
  };

  /* ── Tabs ───────────────────────────────────────────────────── */

  const cabinet = (
    <div class="house-cabinet">
      <nav class="house-diagram" aria-label="The House, its collections and folios">
        <p class="house-diagram__caption">The cabinet</p>
        <div class="house-tree">
          <button
            type="button"
            class="house-node house-node--house"
            aria-current={sel.kind === "house" ? "true" : undefined}
            onClick$={() => select({ kind: "house" })}
          >
            <span class="house-node__kind">The House</span>
            <span class="house-node__name">{houseName || "Your house"}</span>
            <span class="house-node__meta">
              <span class="house-chip">
                {Object.values(state.house.house.dossier).filter((v) => v?.trim()).length} defaults
              </span>
              <span class="house-chip">
                §{state.house.charter.filter((c) => c.ownerRef === "house").length} house charter
              </span>
            </span>
          </button>

          {collections.map((collection) => (
            <div key={collection.id} class="house-drawer">
              <button
                type="button"
                class="house-node house-node--collection"
                aria-current={sel.kind === "collection" && sel.id === collection.id ? "true" : undefined}
                onClick$={() => select({ kind: "collection", id: collection.id })}
              >
                <span class="house-node__kind">Collection</span>
                <span class="house-node__name">{collection.name}</span>
                <span class="house-node__meta">
                  <span class="house-chip">
                    {collection.folioIds.length} {collection.folioIds.length === 1 ? "folio" : "folios"}
                  </span>
                  {state.house.charter.some((c) => c.ownerRef === collection.id) && (
                    <span class="house-chip">
                      §{state.house.charter.filter((c) => c.ownerRef === collection.id).length}
                    </span>
                  )}
                </span>
              </button>
              <div class="house-folders">
                {collection.folioIds
                  .map((fid) => state.folios.find((f) => f.id === fid))
                  .filter((f): f is Folio => !!f)
                  .map(folder)}
                {collection.folioIds.length === 0 && (
                  <p class="house-folder__empty">Empty drawer — file folios from its sheet.</p>
                )}
              </div>
            </div>
          ))}

          <div class="house-drawer">
            <div class="house-node house-node--collection house-node--loose" aria-hidden="true">
              <span class="house-node__kind">Loose folios</span>
              <span class="house-node__name">Not in a collection</span>
            </div>
            <div class="house-folders">
              {looseFolios.map(folder)}
              {looseFolios.length === 0 && state.loaded && (
                <p class="house-folder__empty">Every folio is filed.</p>
              )}
            </div>
          </div>

          <button type="button" class="btn-paper" onClick$={founding}>
            + Found a collection
          </button>
        </div>

        <dl class="house-legend">
          {LEGEND.map(([term, meaning]) => (
            <div key={term}>
              <dt>{term}</dt>
              <dd>{meaning}</dd>
            </div>
          ))}
        </dl>
      </nav>

      {sel.kind === "house"
        ? houseSheet()
        : sel.kind === "collection"
          ? collectionSheet(sel.id)
          : folioSheet(sel.id)}
    </div>
  );

  const entries = state.house.ledger.filter((e) => matchesFilter(e, state.filter));
  const register = (
    <div>
      <div class="house-register__filters" role="group" aria-label="Filter the register">
        {(
          [
            ["all", "Everything"],
            ["amendment", "Amendments"],
            ["dossier", "Dossiers"],
            ["charter", "Charters"],
            ["collection", "Collections"],
          ] as const
        ).map(([value, label]) => (
          <button
            key={value}
            type="button"
            class="house-filter"
            aria-pressed={state.filter === value}
            onClick$={() => (state.filter = value)}
          >
            {label}
          </button>
        ))}
      </div>
      {entries.length === 0 ? (
        <p class="house-empty">
          The register is empty. It fills as dossiers are filed, refined and amended, and as
          charters change.
        </p>
      ) : (
        <div class="house-register">
          {entries.slice(0, 200).map((entry) => (
            <div
              key={entry.id}
              class={[
                "house-register__row",
                { "house-register__row--amendment": entry.source === "amendment" },
              ]}
            >
              <span class="house-register__when">{stamp(entry.at)}</span>
              <span class="house-register__what">
                <strong>{ownerName(state, entry.ownerRef)}</strong>
                <span>
                  {layerStamp(entry.layer === "charter" ? "charter" : entry.source === "amendment" ? "amendment" : entry.layer)}
                </span>
              </span>
              <span class="house-register__diff">
                <span class="house-section__note" style={{ fontStyle: "normal" }}>
                  {LEDGER_SOURCE_LABELS[entry.source]}
                  {entry.field ? ` — ${fieldLabel(entry.field)}` : ""}
                </span>
                {entry.from && <span class="house-register__from">{entry.from}</span>}
                {entry.to && <span>{entry.to}</span>}
                {entry.reason && <span class="house-register__why">{entry.reason}</span>}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const profile = state.profile;
  const t = profile ? thresholdsFor(profile) : null;
  const kinds = Object.keys(KIND_LABELS) as FlowItemKind[];
  const engine = (
    <div class="house-engine">
      <p class="house-sheet__lede" style={{ margin: 0 }}>
        What the flow reader has learned about how you write, the thresholds it derived from
        that, and every decision it made — for tuning the plumbing. Only rhythms and reactions are
        recorded here, never your words.
      </p>
      {profile && t && (
        <div class="house-gauges">
          {[
            ["Pauses learned", String(profile.pauses.length), profile.pauses.length >= 12 ? "Thresholds fitted to you" : "Defaults until 12"],
            ["Stuck after", seconds(t.stuckPauseMs), "a pause after circling"],
            ["Focus after", seconds(t.flowMs), "of steady writing"],
            ["Focus ends after", seconds(t.exitPauseMs), "a pause this long"],
            ["Times in flow", String(profile.flowEntries.length), "confirmed runs"],
            ["Hand overrides", String(profile.overrides), "you left focus yourself"],
            [
              "Usual hours",
              writingHours(profile).map(hourLabel).join(", ") || "—",
              "when you write most",
            ],
          ].map(([label, value, hint]) => (
            <div key={label} class="house-gauge">
              <div class="house-gauge__label">{label}</div>
              <div class="house-gauge__value">{value}</div>
              <div class="house-gauge__hint">{hint}</div>
            </div>
          ))}
        </div>
      )}

      {profile && (
        <section class="house-sheet" style={{ animation: "none" }}>
          <header class="house-section__head">
            <h3 class="house-section__title">What helps you</h3>
            <span class="house-section__note">Weight 1.0 is neutral; used kinds rise, waved-away kinds sink</span>
          </header>
          <div class="house-weights">
            {kinds.map((kind) => {
              const w = kindWeight(profile, kind);
              const s = profile.kinds[kind];
              return (
                <div key={kind} class="house-weight" title={s ? `${s.shown} shown · ${s.engaged} used · ${s.dismissed} set aside` : "Not seen yet"}>
                  <span>{KIND_LABELS[kind]}</span>
                  <span class="house-weight__bar">
                    <span style={{ width: `${(w / 1.8) * 100}%` }} />
                  </span>
                  <span>{w.toFixed(2)}</span>
                </div>
              );
            })}
          </div>
        </section>
      )}

      <section>
        <header class="house-section__head">
          <h3 class="house-section__title">Decision log</h3>
          <span style={{ display: "flex", gap: "0.5rem" }}>
            <button type="button" class="btn-paper" onClick$={exportEngine}>
              Export JSON
            </button>
            <button
              type="button"
              class="btn-paper"
              onClick$={async () => {
                await clearFlowDiagnostics();
                state.log = [];
              }}
            >
              Clear
            </button>
          </span>
        </header>
        {state.log.length === 0 ? (
          <p class="house-empty">
            Nothing logged yet. Write for a while on the desk and the reader's decisions appear
            here as they happen.
          </p>
        ) : (
          <div class="house-log">
            {state.log.map((entry) => (
              <details key={entry.id} class="house-log__row">
                <summary style={{ display: "contents" }}>
                  <span class="house-register__when">
                    {new Date(entry.at).toLocaleTimeString()}
                  </span>
                  <span class={`house-log__kind house-log__kind--${entry.kind}`}>{entry.kind}</span>
                  <span>{entry.summary}</span>
                </summary>
                {entry.detail && (
                  <pre style={{ gridColumn: "1 / -1" }}>{JSON.stringify(entry.detail, null, 2)}</pre>
                )}
              </details>
            ))}
          </div>
        )}
      </section>
    </div>
  );

  return (
    <div class="house">
      <div class="house__inner">
        <header class="house-letterhead">
          <div>
            <p class="house-letterhead__eyebrow">Maison d'édition</p>
            <input
              class="house-letterhead__name"
              value={houseName}
              placeholder="Name your house"
              aria-label="The name of your house"
              onChange$={(_, el) => commit(state, setHouseName(el.value), "The letterhead is reset.")}
            />
            <p class="house-letterhead__motto">
              Everything that tells Twyne what your writing is for — and how it has changed.
            </p>
          </div>
          <div class="house-letterhead__actions">
            <Link href="/library/" class="btn-paper">
              Library
            </Link>
            <Link href="/editor/" class="btn-press">
              ← The desk
            </Link>
          </div>
        </header>

        <div class="house-tabs" role="tablist" aria-label="The House">
          {(
            [
              ["cabinet", "The cabinet", null],
              ["register", "The register", state.house.ledger.length || null],
              ["engine", "Engine room", null],
            ] as const
          ).map(([tab, label, count]) => (
            <button
              key={tab}
              type="button"
              role="tab"
              class="house-tab"
              aria-selected={state.tab === tab}
              onClick$={() => (state.tab = tab)}
            >
              {label}
              {count ? <span class="house-tab__count">{count}</span> : null}
            </button>
          ))}
        </div>

        {!state.loaded ? (
          <p class="house-empty">Opening the cabinet…</p>
        ) : state.tab === "cabinet" ? (
          cabinet
        ) : state.tab === "register" ? (
          register
        ) : (
          engine
        )}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "The House · Twyne",
  meta: [
    {
      name: "description",
      content: "Your house, its collections, dossiers and charters — everything that tells Twyne what your writing is for.",
    },
  ],
};

