1	/**
2	 * The House — where a writer sees, and shapes, everything that tells Twyne
3	 * what their writing is for.
4	 *
5	 *   Cabinet      the hierarchy, drawn as a filing cabinet: the House on its
6	 *                letterhead, collections as drawers, folios as folders. Pick
7	 *                any of them to open its sheet — its dossier, its charter,
8	 *                and exactly what the models are handed.
9	 *   Register     every change to that context, newest first: who or what
10	 *                made it, from what, to what, and why.
11	 *   Engine room  for whoever is tuning the plumbing: what the flow reader has
12	 *                learned, the thresholds it derived, and its decision log.
13	 */
14	import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
15	import { Link, useLocation, type DocumentHead } from "@qwik.dev/router";
16	import "../../components/house/house.css";
17	import type { Folio, ProjectBrief } from "../../types";
18	import {
19	  loadActiveFolioIdFromIdb,
20	  loadAllBriefsFromIdb,
21	  loadFoliosFromIdb,
22	  loadMetaFromIdb,
23	} from "../../utils/idb";
24	import { loadBriefEditions, type BriefEdition } from "../../utils/brief-history";
25	import {
26	  assembleContextStack,
27	  collectionForFolio,
28	  contextForModels,
29	  DOSSIER_FIELD_LABELS,
30	  DOSSIER_FIELDS,
31	  emptyHouseState,
32	  INHERITABLE_FIELDS,
33	  LAYER_LABELS,
34	  LEDGER_SOURCE_LABELS,
35	  type CharterItem,
36	  type CharterScope,
37	  type ContextLayer,
38	  type DossierField,
39	  type HouseState,
40	  type LedgerEntry,
41	} from "../../utils/house-model";
42	import {
43	  createCollection,
44	  deleteCollection,
45	  HOUSE_CHANGED_EVENT,
46	  loadHouseState,
47	  removeCharterItem,
48	  setFolioCollection,
49	  setHouseField,
50	  setHouseName,
51	  updateCollection,
52	  upsertCharterItem,
53	  type HouseChangedDetail,
54	} from "../../utils/house-store";
55	import {
56	  kindWeight,
57	  normalizeProfile,
58	  thresholdsFor,
59	  writingHours,
60	  type FlowProfile,
61	} from "../../utils/flow-profile";
62	import { KIND_LABELS, type FlowItemKind } from "../../utils/flow-items";
63	import {
64	  clearFlowDiagnostics,
65	  FLOW_DIAGNOSTICS_EVENT,
66	  loadFlowDiagnostics,
67	  type DiagnosticEntry,
68	} from "../../utils/flow-diagnostics";
69	
70	type Tab = "cabinet" | "register" | "engine";
71	type Selection =
72	  | { kind: "house" }
73	  | { kind: "collection"; id: string }
74	  | { kind: "folio"; id: string };
75	type RegisterFilter = "all" | "amendment" | "dossier" | "charter" | "collection";
76	
77	interface HouseStore {
78	  loaded: boolean;
79	  tab: Tab;
80	  selection: Selection;
81	  house: HouseState;
82	  folios: Folio[];
83	  briefs: Record<string, ProjectBrief>;
84	  editions: Record<string, BriefEdition[]>;
85	  activeFolioId: string | null;
86	  profile: FlowProfile | null;
87	  log: DiagnosticEntry[];
88	  status: string;
89	  error: boolean;
90	  newArticle: string;
91	  newSeverity: "must" | "prefer";
92	  confirmDissolve: boolean;
93	  filter: RegisterFilter;
94	}
95	
96	/* ── Module helpers (kept out of the component so handlers can use them) ── */
97	
98	async function commit(state: HouseStore, work: Promise<HouseState>, done = "Filed.") {
99	  try {
100	    state.house = await work;
101	    state.status = done;
102	    state.error = false;
103	  } catch (error) {
104	    state.status =
105	      error instanceof Error ? error.message : "That could not be saved on this device.";
106	    state.error = true;
107	  }
108	}
109	
110	/** Typewriter date stamp: 29 SEPT 2026 · 14:05. */
111	function stamp(ts: number): string {
112	  const d = new Date(ts);
113	  const day = d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
114	  const time = d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
115	  return `${day} · ${time}`.toUpperCase();
116	}
117	
118	function seconds(ms: number): string {
119	  return ms >= 60_000 ? `${Math.round(ms / 6_000) / 10} min` : `${Math.round(ms / 1000)} s`;
120	}
121	
122	function hourLabel(hour: number): string {
123	  return new Date(2000, 0, 1, hour).toLocaleTimeString(undefined, { hour: "numeric" });
124	}
125	
126	function ownerName(state: HouseStore, ownerRef: string): string {
127	  if (ownerRef === "house") return state.house.house.name || "The House";
128	  const collection = state.house.collections.find((c) => c.id === ownerRef);
129	  if (collection) return collection.name;
130	  return state.folios.find((f) => f.id === ownerRef)?.name ?? "A folio";
131	}
132	
133	function matchesFilter(entry: LedgerEntry, filter: RegisterFilter): boolean {
134	  switch (filter) {
135	    case "amendment":
136	      return entry.source === "amendment";
137	    case "dossier":
138	      return entry.layer !== "charter" && !!entry.field && entry.source !== "amendment";
139	    case "charter":
140	      return entry.layer === "charter";
141	    case "collection":
142	      return entry.layer === "collection";
143	    default:
144	      return true;
145	  }
146	}
147	
148	function fieldLabel(field?: string): string {
149	  if (!field) return "";
150	  if (field === "must" || field === "prefer") return field === "must" ? "Article (must)" : "Article (prefer)";
151	  return DOSSIER_FIELD_LABELS[field as DossierField] ?? field;
152	}
153	
154	const LEGEND: Array<[string, string]> = [
155	  ["The House", "You. Defaults every piece inherits, and the house charter."],
156	  ["Collection", "A series — a column, a book's chapters, a newsletter. Narrows the House for its folios."],
157	  ["Folio", "One piece. Its dossier has the last word on what it is for."],
158	  ["Charter", "Standards that follow you. Every article from above still applies below."],
159	  ["Edition · Revision", "An edition changes what the words are for; a revision changes the words."],
160	  ["Amendment", "A dossier change the draft itself proposed, and you filed."],
161	];
162	
163	export default component$(() => {
164	  const location = useLocation();
165	  const state = useStore<HouseStore>({
166	    loaded: false,
167	    tab: "cabinet",
168	    selection: { kind: "house" },
169	    house: emptyHouseState(),
170	    folios: [],
171	    briefs: {},
172	    editions: {},
173	    activeFolioId: null,
174	    profile: null,
175	    log: [],
176	    status: "",
177	    error: false,
178	    newArticle: "",
179	    newSeverity: "prefer",
180	    confirmDissolve: false,
181	    filter: "all",
182	  });
183	
184	  // eslint-disable-next-line qwik/no-use-visible-task
185	  useVisibleTask$(async ({ cleanup }) => {
186	    const params = location.url.searchParams;
187	    const [house, folios, briefs, active, profile, log] = await Promise.all([
188	      loadHouseState(),
189	      loadFoliosFromIdb(),
190	      loadAllBriefsFromIdb(),
191	      loadActiveFolioIdFromIdb(),
192	      loadMetaFromIdb<FlowProfile>("flow-profile"),
193	      loadFlowDiagnostics(),
194	    ]);
195	    state.house = house;
196	    state.folios = [...folios].sort((a, b) => b.updatedAt - a.updatedAt);
197	    state.briefs = Object.fromEntries(briefs.map((b) => [b.folioId, b.brief]));
198	    state.activeFolioId = active;
199	    state.profile = normalizeProfile(profile);
200	    state.log = [...log].reverse();
201	    const editions = await Promise.all(folios.map((f) => loadBriefEditions(f.id)));
202	    state.editions = Object.fromEntries(folios.map((f, i) => [f.id, editions[i]]));
203	
204	    const requested = params.get("folio");
205	    const tab = params.get("tab");
206	    if (tab === "register" || tab === "engine") state.tab = tab;
207	    if (requested && folios.some((f) => f.id === requested))
208	      state.selection = { kind: "folio", id: requested };
209	    else if (active && folios.some((f) => f.id === active))
210	      state.selection = { kind: "folio", id: active };
211	    state.loaded = true;
212	
213	    const onHouse = (event: Event) => {
214	      state.house = (event as CustomEvent<HouseChangedDetail>).detail.state;
215	    };
216	    const onLog = (event: Event) => {
217	      state.log = [(event as CustomEvent<DiagnosticEntry>).detail, ...state.log].slice(0, 300);
218	    };
219	    window.addEventListener(HOUSE_CHANGED_EVENT, onHouse);
220	    window.addEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
221	    cleanup(() => {
222	      window.removeEventListener(HOUSE_CHANGED_EVENT, onHouse);
223	      window.removeEventListener(FLOW_DIAGNOSTICS_EVENT, onLog);
224	    });
225	  });
226	
227	  const select = $((selection: Selection) => {
228	    state.selection = selection;
229	    state.newArticle = "";
230	    state.newSeverity = "prefer";
231	    state.confirmDissolve = false;
232	    state.status = "";
233	  });
234	
235	  const addArticle = $(async (scope: CharterScope, ownerRef: string) => {
236	    const text = state.newArticle.trim();
237	    if (!text) return;
238	    await commit(
239	      state,
240	      upsertCharterItem({ scope, ownerRef, text, severity: state.newSeverity, kind: "other" }),
241	      "Article added to the charter.",
242	    );
243	    if (!state.error) state.newArticle = "";
244	  });
245	
246	  const founding = $(async () => {
247	    const before = new Set(state.house.collections.map((c) => c.id));
248	    await commit(state, createCollection("New collection"), "Collection founded.");
249	    const fresh = state.house.collections.find((c) => !before.has(c.id));
250	    if (fresh) await select({ kind: "collection", id: fresh.id });
251	  });
252	
253	  const exportEngine = $(() => {
254	    const blob = new Blob(
255	      [
256	        JSON.stringify(
257	          { exportedAt: new Date().toISOString(), profile: state.profile, log: state.log, house: state.house },
258	          null,
259	          2,
260	        ),
261	      ],
262	      { type: "application/json" },
263	    );
264	    const url = URL.createObjectURL(blob);
265	    const a = document.createElement("a");
266	    a.href = url;
267	    a.download = `twyne-engine-room-${new Date().toISOString().slice(0, 10)}.json`;
268	    a.click();
269	    setTimeout(() => URL.revokeObjectURL(url), 1000);
270	  });
271	
272	  /* ── Pieces of the page ─────────────────────────────────────── */
273	
274	  const houseName = state.house.house.name;
275	  const collections = state.house.collections;
276	  const looseFolios = state.folios.filter((f) => !collectionForFolio(state.house, f.id));
277	  const sel = state.selection;
278	
279	  const layerStamp = (layer: ContextLayer | "charter" | null) =>
280	    layer ? (
281	      <span class={`house-stamp house-stamp--${layer}`}>
282	        {layer === "charter" ? "Charter" : LAYER_LABELS[layer]}
283	      </span>
284	    ) : null;
285	
286	  const folder = (folio: Folio) => {
287	    const brief = state.briefs[folio.id];
288	    const editions = state.editions[folio.id]?.length ?? 0;
289	    const articles = state.house.charter.filter((c) => c.ownerRef === folio.id).length;
290	    return (
291	      <button
292	        key={folio.id}
293	        type="button"
294	        class="house-folder"
295	        aria-current={sel.kind === "folio" && sel.id === folio.id ? "true" : undefined}
296	        onClick$={() => select({ kind: "folio", id: folio.id })}
297	      >
298	        <span class="house-folder__name">{folio.name || "Untitled"}</span>
299	        <span class="house-folder__marks">
300	          {brief ? <span title="Dossier filed">D</span> : <span title="No dossier">—</span>}

