import { chromium } from "@playwright/test";
const BASE = "http://127.0.0.1:5180";
const OUT = process.argv[2] || ".house-shots";
const dark = process.argv.includes("--dark");
const width = Number(process.env.W || 1440);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height: 1000 }, colorScheme: dark ? "dark" : "light" });
const errors = [];
page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
page.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text().slice(0, 300)); });
await page.goto(BASE + "/house/", { waitUntil: "networkidle", timeout: 90000 });
await page.evaluate(async () => {
  const idb = await import("/src/utils/idb.ts");
  const atr = await import("/src/utils/anti-tabula-rasa.ts");
  const store = await import("/src/utils/house-store.ts");
  const now = Date.now();
  const folios = [
    { id: "f-salt", name: "Salt Roads", type: "draft", createdAt: now - 9e8, updatedAt: now - 3e6 },
    { id: "f-tide", name: "The Tide Tables", type: "draft", createdAt: now - 8e8, updatedAt: now - 6e6 },
    { id: "f-letter", name: "Letter to a Young Editor", type: "draft", createdAt: now - 7e8, updatedAt: now - 9e7 },
    { id: "f-notes", name: "Notes on Marginalia", type: "notes", createdAt: now - 5e8, updatedAt: now - 2e8 },
  ];
  await idb.saveFoliosToIdb(folios);
  await idb.saveActiveFolioIdToIdb("f-salt");
  const brief = (a) => ({ answers: { workingTitle: "", format: "", audience: "", goal: "", tone: "", constraints: "", successSignal: "", ...a }, attachments: [], completedAt: now, updatedAt: now });
  await atr.saveProjectBriefForFolio("f-salt", brief({ workingTitle: "Salt Roads", goal: "Trace how salt shaped the old trade routes of the Adriatic", format: "Long-form essay, 4,000 words" }));
  await atr.saveProjectBriefForFolio("f-salt", brief({ workingTitle: "Salt Roads", goal: "Trace how salt shaped the old trade routes, and what the roads became", format: "Long-form essay, 4,000 words", tone: "Unhurried, a little wry" }), { source: "amendment", reason: "The draft kept returning to what the roads became." });
  await atr.saveProjectBriefForFolio("f-tide", brief({ workingTitle: "The Tide Tables", goal: "Explain tidal prediction to non-sailors" }));
  let s = await store.setHouseName("Maison Diogène");
  s = await store.setHouseField("audience", "Curious general readers of a literary quarterly");
  s = await store.setHouseField("tone", "Plain, exact, warm; no throat-clearing");
  s = await store.createCollection("Coastal Essays");
  const col = s.collections[0];
  s = await store.updateCollection(col.id, { description: "A series of essays about the edges of the sea.", field: ["format", "Essay, 3,000–5,000 words"] });
  s = await store.setFolioCollection("f-salt", col.id);
  s = await store.setFolioCollection("f-tide", col.id);
  s = await store.upsertCharterItem({ scope: "house", ownerRef: "house", text: "Cite a primary source for every statistic", severity: "must", kind: "evidence" });
  s = await store.upsertCharterItem({ scope: "collection", ownerRef: col.id, text: "Every essay opens on a scene, not a thesis", severity: "prefer", kind: "structure" });
  s = await store.upsertCharterItem({ scope: "folio", ownerRef: "f-salt", text: "Stay under 4,500 words", severity: "must", kind: "length" });
  await idb.saveMetaToIdb("flow-profile", { version: 1, pauses: Array.from({length: 30}, (_, i) => 4000 + i * 700), runs: Array.from({length: 20}, (_, i) => 30000 + i * 5000), flowEntries: [95000, 120000, 88000, 140000, 101000, 99000], hours: Array.from({length: 24}, (_, h) => (h >= 6 && h <= 9 ? 30 : h >= 21 ? 12 : 1)), kinds: { comment: { shown: 20, engaged: 12, dismissed: 3 }, echo: { shown: 10, engaged: 1, dismissed: 7 }, work: { shown: 6, engaged: 4, dismissed: 0 } }, overrides: 2, updatedAt: now });
  const diag = await import("/src/utils/flow-diagnostics.ts");
  diag.logFlow("mode", "working → flow", { runMs: 95000 });
  diag.logFlow("jev", "Gather: 2 echoes, 1 work", { tokens: 1840 });
  diag.logFlow("surface", "Held 3 items (flow)", { held: 3 });
  await new Promise((r) => setTimeout(r, 2500));
});
const shots = [
  ["cabinet-folio", "/house/?folio=f-salt"],
  ["cabinet-house", "/house/"],
  ["register", "/house/?tab=register"],
  ["engine", "/house/?tab=engine"],
];
for (const [name, path] of shots) {
  await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 90000 });
  await page.waitForSelector(".house-tab", { timeout: 30000 });
  await page.waitForFunction(() => !document.querySelector(".house-empty") || !/Opening/.test(document.querySelector(".house-empty").textContent), null, { timeout: 30000 });
  if (name === "cabinet-house") await page.click(".house-node--house").catch(() => {});
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${OUT}/${name}${dark ? "-dark" : ""}-${width}.png`, fullPage: true });
}
// collection sheet
await page.goto(BASE + "/house/", { waitUntil: "networkidle" });
await page.waitForSelector(".house-drawer, .house-node--collection", { timeout: 30000 }).catch(() => {});
const col = await page.$(".house-node--collection");
if (col) { await col.click(); await page.waitForTimeout(500); await page.screenshot({ path: `${OUT}/cabinet-collection${dark ? "-dark" : ""}-${width}.png`, fullPage: true }); }
console.log(errors.join("\n") || "no errors");
await browser.close();
EOF
timeout 280 node .house-shots/shoot.mjs .house-shots 2>&1 | tail -20; ls .house-shots

