1	/**
2	 * The margins as the conductor sees fit to fill them.
3	 *
4	 * Right margin, the room: notes and replies as they are written, sources the
5	 * Apparatus found, the works the draft names, the charter, the dossier's
6	 * amendments. Left margin, the archive: what the writer has written before
7	 * that this passage echoes, and what their dossier already holds.
8	 *
9	 * Every card sits level with the passage it speaks to. Hover one — or hover
10	 * a marked passage in the text — and a proofreader's bracket and a drawn line
11	 * join the card to its passage, and to every other card on that passage.
12	 * Nothing here decides what appears; `flow-conductor.ts` does.
13	 */
14	import {
15	  $,
16	  component$,
17	  useSignal,
18	  useStore,
19	  useVisibleTask$,
20	} from "@qwik.dev/core";
21	import {
22	  FLOW_EVENT,
23	  flowController,
24	  flowSnapshot,
25	  type FlowSnapshot,
26	} from "../editor/extensions/flow-conductor";
27	import {
28	  KIND_LABELS,
29	  SIDE_FOR,
30	  stackCards,
31	  type FlowItem,
32	} from "../../utils/flow-items";
33	import type { FlowMode } from "../../utils/flow-state";
34	
35	const ROOM_WIDTH = 268;
36	const ARCHIVE_WIDTH = 212;
37	const GUTTER = 28;
38	
39	interface Placed {
40	  item: FlowItem;
41	  top: number;
42	  side: "room" | "archive";
43	}
44	
45	interface Line {
46	  d: string;
47	  color: string;
48	  dashed: boolean;
49	}
50	
51	interface Mark {
52	  x: number;
53	  y: number;
54	  w: number;
55	  h: number;
56	  color: string;
57	}
58	
59	interface Bracket {
60	  d: string;
61	  color: string;
62	}
63	
64	interface SurfaceState {
65	  mode: FlowMode;
66	  enabled: boolean;
67	  items: FlowItem[];
68	  held: number;
69	  expanded: boolean;
70	  peekId: string | null;
71	  hoverId: string | null;
72	  placed: Placed[];
73	  room: "rail" | "dock";
74	  archive: boolean;
75	  lines: Line[];
76	  marks: Mark[];
77	  brackets: Bracket[];
78	  width: number;
79	  height: number;
80	  drafts: Record<string, string>;
81	  busy: Record<string, boolean>;
82	  notices: Record<string, string>;
83	}
84	
85	const accent = (item: FlowItem) =>
86	  item.color ||
87	  (item.kind === "echo" || item.kind === "shelf"
88	    ? "var(--color-cobalt)"
89	    : item.kind === "charter" || item.kind === "amendment"
90	      ? "var(--color-vermilion)"
91	      : item.kind === "work"
92	        ? "var(--color-mustard)"
93	        : "var(--color-sage)");
94	
95	const clip = (text: string, n: number) =>
96	  text.length > n ? `${text.slice(0, n - 1).trimEnd()}…` : text;
97	
98	export const FlowSurface = component$<{ zen: boolean; readOnly?: boolean }>(
99	  (props) => {
100	    const root = useSignal<HTMLDivElement>();
101	    const state = useStore<SurfaceState>({
102	      mode: "working",
103	      enabled: false,
104	      items: [],
105	      held: 0,
106	      expanded: false,
107	      peekId: null,
108	      hoverId: null,
109	      placed: [],
110	      room: "rail",
111	      archive: true,
112	      lines: [],
113	      marks: [],
114	      brackets: [],
115	      width: 0,
116	      height: 0,
117	      drafts: {},
118	      busy: {},
119	      notices: {},
120	    });
121	
122	    // eslint-disable-next-line qwik/no-use-visible-task
123	    useVisibleTask$(({ cleanup }) => {
124	      const el = root.value;
125	      const canvas = el?.closest<HTMLElement>(".page-canvas");
126	      const scroller = canvas?.parentElement;
127	      if (!el || !canvas || !scroller) return;
128	      let frame = 0;
129	      let latest: FlowSnapshot = flowSnapshot();
130	
131	      const itemsToShow = (): FlowItem[] => {
132	        const controller = flowController();
133	        const all = controller?.items() ?? [];
134	        const base = state.expanded && latest.mode !== "flow" ? all : latest.visible;
135	        const peek = state.peekId && all.find((i) => i.id === state.peekId);
136	        const list = peek && !base.some((i) => i.id === peek.id) ? [...base, peek] : base;
137	        return list.map((i) => JSON.parse(JSON.stringify(i)) as FlowItem);
138	      };
139	
140	      const layout = () => {
141	        cancelAnimationFrame(frame);
142	        frame = requestAnimationFrame(() => {
143	          const controller = flowController();
144	          const canvasRect = canvas.getBoundingClientRect();
145	          const scrollerRect = scroller.getBoundingClientRect();
146	          state.width = canvasRect.width;
147	          state.height = canvasRect.height;
148	          const rightRoom = scrollerRect.right - canvasRect.right;
149	          const leftRoom = canvasRect.left - scrollerRect.left;
150	          state.room = rightRoom >= ROOM_WIDTH + GUTTER + 8 ? "rail" : "dock";
151	          state.archive = leftRoom >= ARCHIVE_WIDTH + GUTTER + 8;
152	
153	          const items = itemsToShow();
154	          const caret = controller?.cursorTop();
155	          const fallbackTop = caret != null ? caret - canvasRect.top : 0;
156	          const want = items.map((item) => {
157	            const first = controller?.anchorRects(item)[0]?.[0];
158	            const side =
159	              SIDE_FOR[item.kind] === "archive" && state.archive ? "archive" : "room";
160	            const card = el.querySelector<HTMLElement>(
161	              `[data-flow-card="${CSS.escape(item.id)}"]`,
162	            );
163	            return {
164	              item,
165	              side,
166	              id: item.id,
167	              top: (first ? first.top - canvasRect.top : fallbackTop) - 4,
168	              height: card?.offsetHeight || 120,
169	            } as const;
170	          });
171	
172	          // Step around the live tool card on the right and the tool shelf
173	          // on the left, so nothing is ever drawn over them.
174	          const rel = (node: Element | null) => {
175	            if (!node) return null;
176	            const r = node.getBoundingClientRect();
177	            return r.height ? { top: r.top - canvasRect.top, height: r.height } : null;
178	          };
179	          const tool = rel(canvas.querySelector(".in-flow-rail"));
180	          const shelf = rel(canvas.querySelector(".in-flow-shelf__inner"));
181	          const roomTops = stackCards(
182	            want.filter((w) => w.side === "room"),
183	            tool ? [tool] : [],
184	          );
185	          const archiveTops = stackCards(
186	            want.filter((w) => w.side === "archive"),
187	            shelf ? [shelf] : [],
188	          );
189	          state.placed = want.map((w) => ({
190	            item: w.item,
191	            side: w.side,
192	            top: (w.side === "room" ? roomTops : archiveTops)[w.id] ?? w.top,
193	          }));
194	          state.items = items;
195	          drawConnections();
196	        });
197	      };
198	
199	      /** Brackets, highlights and lines for whatever is hovered. */
200	      const drawConnections = () => {
201	        const controller = flowController();
202	        const id = state.hoverId ?? state.peekId;
203	        const focus = id && state.placed.find((p) => p.item.id === id);
204	        if (!controller || !focus) {
205	          state.lines = [];
206	          state.marks = [];
207	          state.brackets = [];
208	          return;
209	        }
210	        const canvasRect = canvas.getBoundingClientRect();
211	        const text = canvas.querySelector("#twyne-editor-mount .ProseMirror");
212	        const textRect = (text ?? canvas).getBoundingClientRect();
213	        const textLeft = textRect.left - canvasRect.left;
214	        const textRight = textRect.right - canvasRect.left;
215	        const anchors = new Set(focus.item.anchors);
216	        // Every card that shares a passage with the hovered one, or that it
217	        // links to, is part of the same conversation.
218	        const related = state.placed.filter(
219	          (p) =>
220	            p === focus ||
221	            focus.item.links?.includes(p.item.id) ||
222	            p.item.links?.includes(focus.item.id) ||
223	            p.item.anchors.some((a) => anchors.has(a)),
224	        );
225	        const lines: Line[] = [];
226	        const marks: Mark[] = [];
227	        const brackets: Bracket[] = [];
228	        for (const placed of related) {
229	          const color = accent(placed.item);
230	          const primary = placed === focus;
231	          for (const group of controller.anchorRects(placed.item)) {
232	            const tops = group.map((r) => r.top - canvasRect.top);
233	            const bottoms = group.map((r) => r.bottom - canvasRect.top);
234	            const top = Math.min(...tops);
235	            const bottom = Math.max(...bottoms);
236	            if (primary)
237	              for (const r of group)
238	                marks.push({
239	                  x: r.left - canvasRect.left,
240	                  y: r.top - canvasRect.top,
241	                  w: r.width,
242	                  h: r.height,
243	                  color,
244	                });
245	            // A proofreader's bracket in the gutter on the card's side.
246	            const onRight = placed.side === "room";
247	            const bx = onRight ? textRight + 10 : textLeft - 10;
248	            const tick = onRight ? -5 : 5;
249	            brackets.push({
250	              d: `M ${bx + tick} ${top} H ${bx} V ${bottom} H ${bx + tick}`,
251	              color,
252	            });
253	            const cardX = onRight ? state.width + GUTTER : -GUTTER;
254	            const cardY = placed.top + 20;
255	            const midY = (top + bottom) / 2;
256	            const bend = onRight ? 36 : -36;
257	            lines.push({
258	              d: `M ${cardX} ${cardY} C ${cardX - bend} ${cardY}, ${bx + bend} ${midY}, ${bx + (onRight ? 3 : -3)} ${midY}`,
259	              color,
260	              dashed: !primary,
261	            });
262	          }
263	        }
264	        state.lines = lines;
265	        state.marks = marks;
266	        state.brackets = brackets;
267	      };
268	
269	      const onSnapshot = (event: Event) => {
270	        const next = (event as CustomEvent<FlowSnapshot>).detail;
271	        if (next.mode !== latest.mode && next.mode !== "working" && next.mode !== "stuck")
272	          state.expanded = false;
273	        latest = next;
274	        state.mode = next.mode;
275	        state.enabled = next.enabled;
276	        state.held = next.held;
277	        layout();
278	      };
279	
280	      // Hovering a marked passage in the text peeks its card, even one that
281	      // is waiting — the writer asked by pointing at it.
282	      const onOver = (event: Event) => {
283	        const target = event.target as Element | null;
284	        const comment = target?.closest<HTMLElement>("[data-comment-id]");
285	        const note = target?.closest<HTMLElement>("[data-persona-note-id]");
286	        const id = comment
287	          ? `comment:${comment.dataset.commentId}`
288	          : note
289	            ? `note:${note.dataset.personaNoteId}`
290	            : null;
291	        if (id === state.peekId) return;
292	        state.peekId = id;
293	        layout();
294	      };
295	
296	      window.addEventListener(FLOW_EVENT, onSnapshot);
297	      window.addEventListener("resize", layout);
298	      window.addEventListener("twyne:content", layout);
299	      scroller.addEventListener("scroll", layout, { passive: true });
300	      canvas.addEventListener("pointerover", onOver);
301	      const observer = new ResizeObserver(layout);
302	      observer.observe(canvas);
303	      onSnapshot(new CustomEvent(FLOW_EVENT, { detail: flowSnapshot() }));
304	      cleanup(() => {
305	        cancelAnimationFrame(frame);
306	        window.removeEventListener(FLOW_EVENT, onSnapshot);
307	        window.removeEventListener("resize", layout);
308	        window.removeEventListener("twyne:content", layout);
309	        scroller.removeEventListener("scroll", layout);
310	        canvas.removeEventListener("pointerover", onOver);
311	        observer.disconnect();
312	      });
313	    });
314	
315	    const hover = $((id: string | null) => {
316	      state.hoverId = id;
317	      window.dispatchEvent(new CustomEvent("twyne:content"));
318	    });
319	
320	    const dismiss = $((id: string) => {
321	      flowController()?.dismiss(id);
322	      if (state.hoverId === id) state.hoverId = null;
323	    });
324	
325	    const draft = $(async (id: string) => {
326	      state.busy = { ...state.busy, [id]: true };
327	      state.notices = { ...state.notices, [id]: "" };
328	      const text = await flowController()?.draftAmendment(id);
329	      state.busy = { ...state.busy, [id]: false };
330	      if (text) state.drafts = { ...state.drafts, [id]: text };
331	      else
332	        state.notices = {
333	          ...state.notices,
334	          [id]: "No model is set up to draft it — write the new wording yourself.",
335	        };
336	    });
337	
338	    const file = $(async (id: string) => {
339	      state.busy = { ...state.busy, [id]: true };
340	      const error = await flowController()?.fileAmendment(id, state.drafts[id] ?? "");
341	      state.busy = { ...state.busy, [id]: false };
342	      state.notices = { ...state.notices, [id]: error ?? "" };
343	    });
344	
345	    if (props.zen || props.readOnly) return <div ref={root} hidden />;
346	
347	    const card = (placed: Placed) => {
348	      const { item } = placed;
349	      const color = accent(item);
350	      const reply = item.data?.reply;
351	      return (
352	        <article
353	          key={item.id}
354	          data-flow-card={item.id}
355	          class={[
356	            "flow-card",
357	            `flow-card--${item.kind}`,
358	            { "is-hovered": state.hoverId === item.id || state.peekId === item.id },
359	          ]}
360	          style={{
361	            top: `${placed.top}px`,
362	            "--flow-accent": color,
363	          }}
364	          onMouseEnter$={() => hover(item.id)}
365	          onMouseLeave$={() => hover(null)}
366	          onFocusIn$={() => hover(item.id)}
367	          onFocusOut$={() => hover(null)}
368	        >
369	          <header class="flow-card__head">
370	            <span class="flow-card__kicker">
371	              {item.kind === "persona-note" && item.byline
372	                ? item.byline
373	                : KIND_LABELS[item.kind]}
374	              {item.kind === "echo" && item.folioName ? ` · ${item.folioName}` : ""}
375	            </span>
376	            <button
377	              type="button"
378	              class="flow-card__close"
379	              onClick$={() => dismiss(item.id)}
380	              aria-label="Set this aside"
381	              title="Set aside — it won't come back"
382	            >
383	              ✕
384	            </button>
385	          </header>
386	
387	          {(item.kind === "charter" || item.kind === "amendment") && (
388	            <span class="flow-stamp" aria-hidden="true">
389	              {item.kind === "charter" ? "Charte" : "Avenant"}
390	            </span>
391	          )}
392	
393	          {item.kind === "work" && item.work ? (
394	            <a
395	              class={`flow-work flow-work--${item.work.medium}`}
396	              href={item.work.url ?? undefined}
397	              target="_blank"
398	              rel="noopener noreferrer"
399	              onClick$={() => flowController()?.engage(item.id)}
400	            >
401	              <span class="flow-work__sleeve">
402	                {item.work.cover ? (
403	                  <img
404	                    src={item.work.cover}
405	                    alt=""
406	                    width={72}
407	                    height={item.work.medium === "book" ? 108 : 72}
408	                    loading="lazy"
409	                    referrerPolicy="no-referrer"
410	                  />
411	                ) : (
412	                  <span class="flow-work__blank">{item.work.title.slice(0, 1)}</span>
413	                )}
414	                {(item.work.medium === "album" || item.work.medium === "song") && (
415	                  <span class="flow-work__disc" aria-hidden="true" />
416	                )}
417	              </span>
418	              <span class="flow-work__text">
419	                <span class="flow-work__medium">{item.work.medium}</span>
420	                <strong>{item.work.title}</strong>
421	                {item.body && <span>{item.body}</span>}
422	              </span>
423	            </a>
424	          ) : (
425	            <button
426	              type="button"
427	              class="flow-card__body"
428	              onClick$={() => flowController()?.focusAnchor(item)}
429	              title="Go to the passage"
430	            >
431	              {item.kind !== "persona-note" || item.title ? (
432	                <strong class="flow-card__title">{item.title}</strong>
433	              ) : null}
434	              {item.body && (
435	                <span class={item.kind === "echo" ? "flow-card__carbon" : "flow-card__text"}>
436	                  {clip(item.body, item.kind === "echo" ? 360 : 280)}
437	                </span>
438	              )}
439	            </button>
440	          )}
441	
442	          {reply !== undefined && (reply || item.streaming) && (
443	            <p class={["flow-card__reply", { "is-streaming": item.streaming }]}>
444	              <span class="flow-card__reply-by">{item.data?.replyAuthor}</span>
445	              {clip(reply ?? "", 420)}
446	            </p>
447	          )}
448	
449	          {item.kind === "amendment" && (
450	            <div class="flow-amend">
451	              <textarea
452	                class="flow-amend__input"
453	                rows={3}
454	                placeholder="What is this piece for now?"
455	                value={state.drafts[item.id] ?? ""}
456	                onInput$={(_, target) => {
457	                  state.drafts = { ...state.drafts, [item.id]: target.value };
458	                }}
459	                aria-label="New wording for the dossier"
460	              />
461	              <div class="flow-amend__actions">
462	                <button
463	                  type="button"
464	                  class="flow-link"
465	                  disabled={state.busy[item.id]}
466	                  onClick$={() => draft(item.id)}
467	                >
468	                  {state.busy[item.id] ? "Drafting…" : "Draft it for me"}
469	                </button>
470	                <button
471	                  type="button"
472	                  class="btn-paper flow-mini"
473	                  disabled={state.busy[item.id] || !(state.drafts[item.id] ?? "").trim()}
474	                  onClick$={() => file(item.id)}
475	                >
476	                  File it
477	                </button>
478	              </div>
479	              {state.notices[item.id] && (
480	                <p class="flow-card__notice" role="status">
481	                  {state.notices[item.id]}
482	                </p>
483	              )}
484	            </div>
485	          )}
486	
487	          {(item.byline && item.kind !== "persona-note") || item.url ? (
488	            <footer class="flow-card__foot">
489	              {item.byline && item.kind !== "persona-note" && <span>{item.byline}</span>}
490	              {item.url && item.kind !== "work" && (
491	                <a
492	                  href={item.url}
493	                  target="_blank"
494	                  rel="noopener noreferrer"
495	                  class="flow-link"
496	                  onClick$={() => flowController()?.engage(item.id)}
497	                >
498	                  Open
499	                </a>
500	              )}
501	            </footer>
502	          ) : null}
503	        </article>
504	      );
505	    };
506	
507	    const room = state.placed.filter((p) => p.side === "room");
508	    const archive = state.placed.filter((p) => p.side === "archive");
509	    const waiting = state.held > 0 && state.enabled && state.mode !== "flow";
510	
511	    return (
512	      <div
513	        ref={root}
514	        class="flow-surface"
515	        data-mode={state.mode}
516	        aria-label="Margin notes and connections"
517	      >
518	        <svg
519	          class="flow-overlay"
520	          width={state.width}
521	          height={state.height}
522	          aria-hidden="true"
523	        >
524	          {state.marks.map((m, i) => (
525	            <rect
526	              key={`m${i}`}
527	              class="flow-overlay__mark"
528	              x={m.x - 1}
529	              y={m.y + m.h - 3}
530	              width={m.w + 2}
531	              height={3}
532	              style={{ fill: m.color }}
533	            />
534	          ))}
535	          {state.brackets.map((b, i) => (
536	            <path key={`b${i}`} class="flow-overlay__bracket" d={b.d} style={{ stroke: b.color }} />
537	          ))}
538	          {state.lines.map((l, i) => (
539	            <path
540	              key={`l${i}`}
541	              class={["flow-overlay__line", { "is-dashed": l.dashed }]}
542	              d={l.d}
543	              style={{ stroke: l.color }}
544	            />
545	          ))}
546	        </svg>
547	
548	        {state.archive && (
549	          <div class="flow-column flow-column--archive" style={{ width: `${ARCHIVE_WIDTH}px` }}>
550	            {archive.map(card)}
551	          </div>
552	        )}
553	
554	        {state.room === "rail" ? (
555	          <div class="flow-column flow-column--room" style={{ width: `${ROOM_WIDTH}px` }}>
556	            {room.map(card)}
557	            {waiting && (
558	              <button
559	                type="button"
560	                class="flow-waiting"
561	                style={{
562	                  top: `${Math.max(0, ...room.map((p) => p.top + 140))}px`,
563	                }}
564	                onClick$={() => {
565	                  state.expanded = !state.expanded;
566	                  window.dispatchEvent(new CustomEvent("twyne:content"));
567	                }}
568	              >
569	                {state.expanded ? "Fewer" : `${state.held} more in the margin`}
570	              </button>
571	            )}
572	          </div>
573	        ) : (
574	          room.length > 0 && (
575	            <div class="flow-dock" role="complementary" aria-label="From the margin">
576	              {card({ ...room[0], top: 0 })}
577	              {room.length + state.held > 1 && (
578	                <p class="flow-dock__more">
579	                  {room.length + state.held - 1} more when there's room
580	                </p>
581	              )}
582	            </div>
583	          )
584	        )}
585	      </div>
586	    );
587	  },
588	);
589

