    }
    store.userCommentPopover = {
      mode: "thread",
      visible: true,
      id: c.id,
      author: c.author,
      text: c.text,
      quote: c.anchor ?? markEl.textContent ?? "",
      createdAt: c.createdAt,
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: null,
      to: null,
      resolved: c.resolved,
      replies: c.replies,
      draft: "",
    };
  },
);

