import { expect, test, type Page } from "@playwright/test";

const DOC =
  "<h1>Harbour Notes</h1>" +
  Array.from(
    { length: 40 },
    (_, i) => `<p>Paragraph ${i + 1} of the harbour survey, tide by tide.</p>`,
  ).join("");

async function seed(page: Page, pagination: "paginated" | "continuous") {
  await page.goto("/");
  await page.evaluate(
    async ({ html, pagination }) => {
      const db: IDBDatabase = await new Promise((resolve, reject) => {
        const req = indexedDB.open("twyne", 2);
        req.onupgradeneeded = () => {
          const d = req.result;
          for (const [name, keyPath] of [
            ["folios", "id"],
            ["folio-content", "folioId"],
            ["brief", "folioId"],
            ["comments", "id"],
            ["personas", "id"],
            ["meta", "key"],
            ["ai-settings", "key"],
            ["lix-blob", "key"],
            ["voice-notes", "id"],
          ] as const) {
            if (!d.objectStoreNames.contains(name))
              d.createObjectStore(name, { keyPath });
          }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });
      const now = Date.now();
      const id = "e2e-select-all";
      await new Promise<void>((resolve, reject) => {
        const t = db.transaction(
          ["folios", "folio-content", "meta"],
          "readwrite",
        );
        t.objectStore("folios").put({
          id,
          name: "Select-all fixture",
          type: "draft",
          createdAt: now,
          updatedAt: now,
          layout: { pagination },
        });
        t.objectStore("folio-content").put({
          folioId: id,
          html,
          updatedAt: now,
        });
        t.objectStore("meta").put({
          key: "active-folio-id",
          value: id,
          updatedAt: now,
        });

