cat > .house-shots/margin.mjs <<'EOF'
import { chromium } from "@playwright/test";
const BASE = "http://127.0.0.1:5180";
const width = Number(process.env.W || 1600);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height: 1000 } });
const errs = [];
page.on("pageerror", (e) => errs.push("pageerror: " + e.message));
await page.goto(BASE + "/house/", { waitUntil: "load", timeout: 90000 });
await page.waitForTimeout(3000);
await page.evaluate(async () => {
  const idb = await import("/src/utils/idb.ts");
  const uc = await import("/src/utils/user-comments.ts");
  const now = Date.now();
  const id = "f-margin";
  await idb.saveFoliosToIdb([{ id, name: "Salt Roads", type: "draft", createdAt: now, updatedAt: now }]);
  await idb.saveActiveFolioIdToIdb(id);
  const paras = Array.from({ length: 6 }, (_, i) => `<p>Paragraph ${i + 1}: the salt caravans left before dawn, and the road bent with the coast for a week of walking.</p>`);
  paras[1] = `<p>The traders <span data-persona-note-id="n1" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="This sentence carries three ideas; let the second breathe." data-persona-note-quote="weighed their loads by the handful">weighed their loads by the handful</span> and argued about the weather.</p>`;
  paras[3] = `<p>By the fourth day <span class="twyne-comment-mark" data-comment-id="c1" data-comment-author="You">the road forgot the sea entirely</span> and turned inland.</p>`;
  await idb.saveFolioContentToIdb(id, paras.join(""));
  await uc.saveUserComments([{ id: "c1", folioId: id, text: "Is this literally true? Check the map.", author: "You", anchor: "the road forgot the sea entirely", resolved: false, createdAt: now, updatedAt: now, replies: [] }]);
  await idb.saveMetaToIdb("flow-reading-enabled", true);
});
await page.goto(BASE + "/editor/", { waitUntil: "load", timeout: 90000 });
await page.waitForSelector(".ProseMirror", { timeout: 60000 });
await page.waitForTimeout(6000);
const report = async (label) => {
  const r = await page.evaluate(() => ({
    flowCards: [...document.querySelectorAll(".flow-card")].map((c) => `${c.getAttribute("data-flow-card")}${c.classList.contains("is-unfolded") ? "(unfolded)" : ""}`),
    popovers: [...document.querySelectorAll(".manuscript-comment-card")].map((c) => `${c.className.replace(/\s+/g, ".")} margin=${c.getAttribute("data-margin-item")} left=${Math.round(c.getBoundingClientRect().left)} top=${Math.round(c.getBoundingClientRect().top)} w=${Math.round(c.getBoundingClientRect().width)}`),
    chips: document.querySelectorAll(".twyne-mark-anchor").length,
    rail: !!document.querySelector(".flow-column--room"),
  }));
  console.log(label, JSON.stringify(r));
};
await report("initial");
await page.screenshot({ path: `.house-shots/margin-0-${width}.png` });
const chip = page.locator('.twyne-mark-anchor[data-anchor-kind="note"]').first();
if (await chip.count()) { await chip.click(); await page.waitForTimeout(1200); await report("after note chip"); await page.screenshot({ path: `.house-shots/margin-1-note-${width}.png` }); }
await page.mouse.click(10, 500); await page.waitForTimeout(600);
const cchip = page.locator('.twyne-mark-anchor[data-anchor-kind="comment"]').first();
if (await cchip.count()) { await cchip.click(); await page.waitForTimeout(1200); await report("after comment chip"); await page.screenshot({ path: `.house-shots/margin-2-comment-${width}.png` }); }
await page.mouse.wheel(0, 200); await page.waitForTimeout(800); await report("after scroll");
await page.keyboard.press("Escape"); await page.waitForTimeout(600); await report("after escape");
console.log(errs.slice(0, 5).join("\n") || "no page errors");
await browser.close();
EOF
