                </button>
                <button
                  onClick$={props.onAccept$}
                  disabled={suggestion.busy}
                  class="btn-press text-xs"
                >
                  {suggestion.busy ? "Stamping…" : "Accept & stamp"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {props.stampVisible && (
        <div
          class="approval-stamp-overlay"
          role="status"
          aria-label="Revision applied"
        >
          <WorkflowStamp kind="revised" />
        </div>
      )}
    </>
  );
});
