1	/**
2	 * The galley slip: what one run of focused writing amounted to.
3	 *
4	 * The flow conductor opens a session when the page goes into flow and closes
5	 * it when flow ends, then announces the summary with `FLOW_SESSION_EVENT`.
6	 * The margin sets it as a small typed slip; the House keeps the recent ones.
7	 */
8	import { loadMetaFromIdb } from "./idb";
9	
10	export const FLOW_SESSION_EVENT = "twyne:flow-session";
11	
12	export type FlowSessionEnd =
13	  /** A long pause ended the run. */
14	  | "pause"
15	  /** The writer reached for the room (margin, masthead) or pressed Escape. */
16	  | "reached"
...
34	  /** Words a minute across the session. */
35	  wpm: number;
36	  /** Margin items that arrived, or were held back, while the page was quiet. */
37	  waited: number;
38	  /** Dossier amendments proposed during the session. */
39	  amendments: number;
40	  ended: FlowSessionEnd;
41	}
42	
43	export interface SessionSummaryInput {
44	  folioId: string;
45	  startedAt: number;
46	  endedAt: number;
47	  startWords: number;
48	  endWords: number;
49	  waited: ReadonlySet<string>;
50	  amendments: ReadonlySet<string>;
51	  ended: FlowSessionEnd;
52	}
53	
54	/** Net document growth, with a slip only for a minute in flow or 40 words. */
55	export function summarizeSession(input: SessionSummaryInput): FlowSession | null {
56	  const flowMs = Math.max(0, input.endedAt - input.startedAt);
57	  const words = Math.max(0, Math.round(input.endWords - input.startWords));
58	  if (flowMs < 60_000 && words < 40) return null;
59	  return {
60	    id: `${input.folioId}:${input.startedAt}`,
61	    folioId: input.folioId,
62	    startedAt: input.startedAt,
63	    endedAt: input.endedAt,
64	    flowMs,
65	    words,
66	    wpm: flowMs > 0 ? Math.round(words * 60_000 / flowMs) : 0,
67	    waited: input.waited.size,
68	    amendments: input.amendments.size,
69	    ended: input.ended,
70	  };
71	}
72	
73	/** Oldest first, distinct by id, without mutating the supplied history. */
74	export function appendSession(
75	  list: readonly FlowSession[],
76	  session: FlowSession,
77	  max = 30,
78	): FlowSession[] {
79	  const limit = Math.max(0, Math.floor(max));
80	  if (!limit) return [];
81	  const byId = new Map(list.map((entry) => [entry.id, entry]));
82	  byId.set(session.id, session);
83	  return [...byId.values()]
84	    .sort((a, b) => a.endedAt - b.endedAt || a.startedAt - b.startedAt)
85	    .slice(-limit)
86	    .map((entry) => ({ ...entry }));
87	}
88	
89	/** Recent slips live on this device, under the existing IndexedDB meta store. */
90	export async function loadFlowSessions(): Promise<FlowSession[]> {
91	  const stored = await loadMetaFromIdb<FlowSession[]>("flow-sessions");
92	  return Array.isArray(stored) ? stored.slice(-30).map((entry) => ({ ...entry })) : [];
93	}

