    color-mix(in srgb, var(--color-paper) 94%, var(--color-mustard));
  border: 1px solid var(--color-paper-3);
  border-left: 3px double color-mix(in srgb, var(--color-ink) 45%, transparent);
  border-radius: 1px;
  color: var(--color-ink);
  font-family: var(--font-typewriter);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 12px 24px -18px rgb(0 0 0 / 0.5);
  animation: flow-slip-feed 420ms cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes flow-slip-feed {
  from {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    clip-path: inset(0);
    transform: none;
  }
}
.flow-slip__head {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.flow-slip__title {
  color: var(--color-ink);
  font-weight: 700;
}
.flow-slip__head time {
  margin-right: auto;
}
.flow-slip__close {
  padding: 0 0.15rem;
  border: 0;
  background: none;
  color: var(--color-ink-muted);
  font-size: 0.7rem;
  cursor: pointer;
}
.flow-slip__close:hover {
  color: var(--color-vermilion);
}
.flow-slip__rows {
  display: grid;
  gap: 0.1rem;
  margin: 0;
}
.flow-slip__rows > div {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  font-size: 0.72rem;
  line-height: 1.35rem;
}
.flow-slip__rows dt {
  color: var(--color-ink-muted);
}
/* Leader dots, as on a contents page. */
.flow-slip__rows dt::after {
  content: "";
}
.flow-slip__rows > div::after {
  content: none;
}
.flow-slip__rows dd {
  order: 2;
  margin: 0 0 0 auto;
  font-variant-numeric: tabular-nums;
}
.flow-slip__rows > div > dt + dd::before {
  content: none;
}
.flow-slip__rows > div {
  background: radial-gradient(
      circle,
      color-mix(in srgb, var(--color-ink) 30%, transparent) 0.6px,
      transparent 0.9px
    )
    0 0.92rem / 5px 3px repeat-x;
}
.flow-slip__rows dt,
.flow-slip__rows dd {
  padding: 0 0.2rem;
  background: color-mix(in srgb, var(--color-paper) 94%, var(--color-mustard));
}
.flow-slip__rows dt {
  padding-left: 0;
}
.flow-slip__rows dd {
  padding-right: 0;
}
.flow-slip__foot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.66rem;
}
.flow-slip__foot em {
  color: var(--color-ink-light);
  font: italic 0.74rem/1.3 var(--font-serif);
}
.flow-slip__stamp {
  position: absolute;
  right: 0.65rem;
  top: 1.7rem;
  padding: 0.05rem 0.35rem;
  border: 1.5px solid var(--color-vermilion);
  border-radius: 2px;
  color: var(--color-vermilion);
  font: 0.56rem/1.3 var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transform: rotate(-6deg);
  opacity: 0.55;
  pointer-events: none;
}

/* A way in: the one thing Jev offers when the writer is stuck. */
.flow-card--way-in {
  background: color-mix(
    in srgb,
    var(--color-paper) 90%,
    var(--color-periwinkle) 6%
  );
}
.flow-card--way-in .flow-card__title {
  font-style: italic;
}
.flow-way-in {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.3rem 0.6rem;
}
.flow-way-in__hint {
  color: var(--color-ink-muted);
  font: 0.6rem/1.3 var(--font-typewriter);
}

@media print {
  .flow-surface,
  .flow-dock,
  .flow-desk {
    display: none !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .flow-slip,
  .flow-post.is-arriving .flow-post__capsule {
    animation: none;
  }
}

