// Screenshots the desk (pneumatic post, galley slip), the ink ribbon and a
// way-in card by driving the flow snapshot directly. Scratch: delete after.
import { chromium } from "@playwright/test";
const BASE = "http://127.0.0.1:5180";
const width = Number(process.env.W || 1600);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height: 1000 } });
const errs = [];
page.on("pageerror", (e) => errs.push("pageerror: " + e.message));
await page.goto(BASE + "/house/", { waitUntil: "load", timeout: 90000 });
await page.waitForTimeout(2500);
await page.evaluate(async () => {
  const idb = await import("/src/utils/idb.ts");
  const now = Date.now();
  const id = "f-desk";
  await idb.saveFoliosToIdb([{ id, name: "Salt Roads", type: "draft", createdAt: now, updatedAt: now }]);
  await idb.saveActiveFolioIdToIdb(id);
  const paras = Array.from({ length: 9 }, (_, i) => `<p>Paragraph ${i + 1}: the salt caravans left before dawn, and the road bent with the coast for a week of walking, until the dunes began.</p>`);
  await idb.saveFolioContentToIdb(id, paras.join(""));
  await idb.saveMetaToIdb("flow-reading-enabled", true);
});
await page.goto(BASE + "/editor/", { waitUntil: "load", timeout: 90000 });
await page.waitForSelector(".ProseMirror", { timeout: 60000 });
await page.waitForTimeout(5000);

const fire = (detail) =>
  page.evaluate(async (d) => {
    const m = await import("/src/components/editor/extensions/flow-conductor.ts");
    const base = m.flowSnapshot();
    const snap = { ...base, ...d, enabled: true };
    document.documentElement.dataset.flow = snap.mode;
    window.dispatchEvent(new CustomEvent(m.FLOW_EVENT, { detail: snap }));
  }, detail);
const reading = (mode, runMs) => ({ mode, runMs, pauseMs: 0, activeRatio: 0.8, deleteRatio: 0.05, wpm: 38, recentChurn: 0, reason: "" });
const shot = async (name) => {
  await page.waitForTimeout(900);
  await page.screenshot({ path: `.house-shots/desk-${name}-${width}.png` });
  const r = await page.evaluate(() => ({
    post: document.querySelector(".flow-post")?.getAttribute("aria-label") ?? null,
    slip: !!document.querySelector(".flow-slip"),
    ribbon: document.querySelector(".flow-ribbon")?.textContent ?? null,
    ribbonMode: document.querySelector(".flow-ribbon")?.getAttribute("data-mode") ?? null,
    wayIn: !!document.querySelector(".flow-card--way-in"),
    deskOpacity: (() => { const d = document.querySelector(".flow-desk"); return d ? getComputedStyle(d).opacity : null; })(),
  }));
  console.log(name, JSON.stringify(r));
};

await page.locator(".ProseMirror p").nth(4).click();
await fire({ mode: "working", reading: reading("working", 20_000), visible: [], held: 0, heldKinds: {} });
await shot("0-working");
await fire({ mode: "settling", reading: reading("settling", 40_000), visible: [], held: 1, heldKinds: { echo: 1 } });
await shot("1-settling");
await fire({ mode: "flow", reading: reading("flow", 7 * 60_000), visible: [], held: 3, heldKinds: { echo: 1, work: 1, comment: 1 } });
await page.waitForTimeout(200);
await fire({ mode: "flow", reading: reading("flow", 8 * 60_000), visible: [], held: 4, heldKinds: { echo: 1, work: 1, comment: 1, charter: 1 } });
await shot("2-flow");
await page.evaluate(async () => {
  const s = await import("/src/utils/flow-session.ts");
  const now = Date.now();
  window.dispatchEvent(new CustomEvent(s.FLOW_SESSION_EVENT, { detail: { id: "f-desk:1", folioId: "f-desk", startedAt: now - 23 * 60_000, endedAt: now, flowMs: 23 * 60_000, words: 612, wpm: 27, waited: 4, amendments: 1, ended: "pause" } }));
});
await fire({ mode: "working", reading: reading("working", 0), visible: [], held: 4, heldKinds: { echo: 1, work: 1, comment: 1, charter: 1 } });
await shot("3-slip");
await fire({ mode: "stuck", reading: { ...reading("stuck", 0), pauseMs: 30_000 }, visible: [
  { id: "way-in:test", kind: "way-in", anchors: ["Paragraph 5: the salt caravans"], title: "Say it plainly first", body: "Write the sentence as you'd tell it to a friend who has never seen the coast. Dress it afterwards.", createdAt: Date.now(), relevance: 0.8 },
], held: 0, heldKinds: {} });
await shot("4-stuck");
console.log(errs.length ? errs.join("\n") : "no page errors");
await browser.close();

